[187] = {sortid = 187, typeid = 2, chapterid = 2, chaptersort = 11, number = "2-9-1", name = "留守者-1", plot_first = "XH/xh2_9", plot_last = "0", checkpointid = 9001140, picture = "ArtGallery/PlotCg/XH/xh_2_9", introduction = "斯卡蒂將王女和會長的錄影互相發送給對方，引起了一場不大的鬧劇。可是鬧劇結束之後問題依然存在——斯卡蒂將做出何種選擇……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[188] = {sortid = 188, typeid = 2, chapterid = 2, chaptersort = 12, number = "2-9-2", name = "留守者-2", plot_first = "0", plot_last = "XH/xh2_9e", checkpointid = 9001147, picture = "ArtGallery/PlotCg/XH/xh_2_9e", introduction = "斯卡蒂將王女和會長的錄影互相發送給對方，引起了一場不大的鬧劇。可是鬧劇結束之後問題依然存在——斯卡蒂將做出何種選擇……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[189] = {sortid = 189, typeid = 2, chapterid = 2, chaptersort = 13, number = "2-10-1", name = "三位王的軍隊-1", plot_first = "XH/xh2_10", plot_last = "0", checkpointid = 9001180, picture = "ArtGallery/PlotCg/XH/xh_2_10", introduction = "會長和王女離開了斯卡蒂留了下來，她們決定憑自己的能力解決那隱藏著的原罪。可斯卡蒂她們又怎麼可能就此離開，只要找到去往上之島的門，就能回去幫助王女和會長……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[190] = {sortid = 190, typeid = 2, chapterid = 2, chaptersort = 14, number = "2-10-2", name = "三位王的軍隊-2", plot_first = "XH/xh2_10e", plot_last = "0", checkpointid = 9001181, picture = "ArtGallery/PlotCg/XH/xh_2_10e", introduction = "會長和王女離開了斯卡蒂留了下來，她們決定憑自己的能力解決那隱藏著的原罪。可斯卡蒂她們又怎麼可能就此離開，只要找到去往上之島的門，就能回去幫助王女和會長……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[191] = {sortid = 191, typeid = 2, chapterid = 2, chaptersort = 15, number = "2-11", name = "系帶", plot_first = "XH/xh2_11", plot_last = "XH/xh2_11e", checkpointid = 9001188, picture = "ArtGallery/PlotCg/XH/xh_2_11", introduction = "斯卡蒂她們找到了回到上之島的門，會長和王女也找到了那藏著的原罪。斯卡蒂急著去支援王女和會長，但是現在要先過響子她們這關……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[192] = {sortid = 192, typeid = 2, chapterid = 2, chaptersort = 16, number = "2-12", name = "萬策盡", plot_first = "XH/xh2_12", plot_last = "0", checkpointid = 9001200, picture = "ArtGallery/PlotCg/XH/xh_2_12", introduction = "會長在戰鬥中受到了重傷，所幸鈴研製的裝置將她受到的傷害分擔給了響子她們。就在此刻，王女的【王下之劍】正在緩緩出鞘……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[193] = {sortid = 193, typeid = 2, chapterid = 2, chaptersort = 17, number = "2-13", name = "燈火集", plot_first = "XH/xh2_13", plot_last = "0", checkpointid = 9001201, picture = "ArtGallery/PlotCg/XH/xh_2_13", introduction = "被打飛王女和會長正好掉落在斯卡蒂與領航面前，通過她們的描述斯卡蒂終於知道她們所需要面對的敵人是……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[194] = {sortid = 194, typeid = 2, chapterid = 2, chaptersort = 18, number = "2-14", name = "於空中", plot_first = "XH/xh2_14", plot_last = "0", checkpointid = 9001202, picture = "ArtGallery/PlotCg/XH/xh_2_14", introduction = "在領航的幫助下，斯卡蒂終於將巨大化。與此同時【巴哈姆特】也通過通道來到了上之島……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[195] = {sortid = 195, typeid = 2, chapterid = 2, chaptersort = 19, number = "2-15", name = "接踵而至", plot_first = "XH/xh2_15", plot_last = "0", checkpointid = 9001209, picture = "ArtGallery/PlotCg/XH/xh_2_15", introduction = "巴哈姆特在巨大化的斯卡蒂的劍下節節敗退，就在斯卡蒂準備擊殺它的那一刻，巴哈姆特最後的力量發動了……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[196] = {sortid = 196, typeid = 2, chapterid = 2, chaptersort = 20, number = "2-16", name = "終幕", plot_first = "XH/xh2_15e", plot_last = "XH/xh2_16", checkpointid = 9001210, picture = "ArtGallery/PlotCg/XH/xh_2_15e", introduction = "巴哈姆特在巨大化的斯卡蒂的劍下節節敗退，就在斯卡蒂準備擊殺它的那一刻，巴哈姆特最後的力量發動了……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[197] = {sortid = 197, typeid = 2, chapterid = 2, chaptersort = 21, number = "2-17", name = "後日談", plot_first = "XH/xh2_16e", plot_last = "0", checkpointid = 9001224, picture = "ArtGallery/PlotCg/XH/xh_2_16", introduction = "巴哈姆特迎來了它的終局，而在領航與斯卡蒂在這裡的旅程也將畫上句號。雖然註定要分別，但是她們的故事並沒有在此終結……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[198] = {sortid = 198, typeid = 2, chapterid = 5, chaptersort = 1, number = "1-1", name = "蛻皮之蛇", plot_first = "SF/SF_1", plot_last = "0", checkpointid = 900301, picture = "ArtGallery/PlotCg/SF/SF_1", introduction = "在過去的戰役中，耶夢加得被多瑙聯合部隊擊敗——但似乎看起來，這條蛇並沒有像報告中那樣老實地死去……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[199] = {sortid = 199, typeid = 2, chapterid = 5, chaptersort = 2, number = "1-2", name = "少女與駕駛員", plot_first = "SF/SF_2", plot_last = "0", checkpointid = 900302, picture = "ArtGallery/PlotCg/SF/SF_2", introduction = "自出生以來便一直居住在海島的少女——莉比蒂萌生出要離開家鄉的想法，但此時此刻，她卻面臨著空前的危機……原罪。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[200] = {sortid = 200, typeid = 2, chapterid = 5, chaptersort = 3, number = "1-3", name = "“天神”", plot_first = "SF/SF_3", plot_last = "0", checkpointid = 900303, picture = "ArtGallery/PlotCg/SF/SF_3", introduction = "在危機中拯救了莉比蒂的人正是格洛麗亞、羅德尼亞、靜三名駕駛員組成的地區聯合調查小隊，但莉比蒂卻稱呼她們為“天神的使徒”。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[201] = {sortid = 201, typeid = 2, chapterid = 5, chaptersort = 4, number = "1-4", name = "要做多餘的事情", plot_first = "SF/SF_4", plot_last = "0", checkpointid = 900304, picture = "ArtGallery/PlotCg/SF/SF_4", introduction = "在三周前，一直鮮有人拜訪的海島迎來了它久違的訪客，但這位訪客是一名不速之客……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[202] = {sortid = 202, typeid = 2, chapterid = 5, chaptersort = 5, number = "1-5", name = "不開玩笑", plot_first = "SF/SF_5", plot_last = "SF/SF_5e", checkpointid = 900305, picture = "ArtGallery/PlotCg/SF/SF_5", introduction = "地區聯合調查小隊拜訪了莉比蒂居住的村莊，卻遭到了意想不到的阻力。看起來，這裡的人十分排斥不請自來的外來人。正當她們一籌莫展之際，原罪再度襲來。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[203] = {sortid = 203, typeid = 2, chapterid = 5, chaptersort = 6, number = "1-6", name = "突出的優點", plot_first = "SF/SF_6", plot_last = "0", checkpointid = 900306, picture = "ArtGallery/PlotCg/SF/SF_6", introduction = "在村莊遭受不可抗阻力的調查小隊，接到了趕來支援的駕駛員愛麗絲·克雷蒂亞的通知。在一番交流後，她們決定放棄調查，專心保護村莊，可就在這時，靜提出了自己的猜想……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[204] = {sortid = 204, typeid = 2, chapterid = 5, chaptersort = 7, number = "1-7", name = "新生第三研究室防衛班", plot_first = "SF/SF_7", plot_last = "SF/SF_7e", checkpointid = 900307, picture = "ArtGallery/PlotCg/SF/SF_7", introduction = "羅德尼亞與靜被派去調查神廟，在路途上，靜通過交談得知了羅德尼亞與格洛麗亞來自於第三研究室防衛班——那隻在一個月前幾乎全員陣亡的小隊。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[205] = {sortid = 205, typeid = 2, chapterid = 5, chaptersort = 8, number = "1-8", name = "這是我們的爛攤子", plot_first = "SF/SF_8", plot_last = "SF/SF_8e", checkpointid = 900308, picture = "ArtGallery/PlotCg/SF/SF_8", introduction = "“耶夢加得”——本應在一個月前死去的原罪再一次出現在了人類的面前。指揮室做出指示讓三人撤離，“它是我們的爛攤子”，這是羅德尼亞的回答。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[206] = {sortid = 206, typeid = 2, chapterid = 5, chaptersort = 9, number = "1-9", name = "約定的份量", plot_first = "SF/SF_9", plot_last = "0", checkpointid = 900309, picture = "ArtGallery/PlotCg/SF/SF_9", introduction = "不管怎樣的絕境，羅德尼亞都必須要站起來，因為她是一個遵守約定的人。現在，她要履行“揍飛耶夢加得”的約定。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[207] = {sortid = 207, typeid = 2, chapterid = 13, chaptersort = 1, number = "1-1", name = "經此祝聖", plot_first = "1ST/1ST_01", plot_last = "0", checkpointid = 901101, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_01", introduction = "為調查“不明蒼霧”，你與查麗莎以外來者的身份前往珀因雷德——坐落於群巒之間的一座偏遠古城。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[208] = {sortid = 208, typeid = 2, chapterid = 13, chaptersort = 2, number = "1-2-1", name = "儀式與榮耀", plot_first = "1ST/1ST_02A", plot_last = "0", checkpointid = 901104, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_02", introduction = "尖塔聳立，鐘聲盈耳，這便是由聖濯教會掌管的西區，也是你正式踏上的土地。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[209] = {sortid = 209, typeid = 2, chapterid = 13, chaptersort = 3, number = "1-2-2", name = "規則與理性", plot_first = "1ST/1ST_02B", plot_last = "0", checkpointid = 901112, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_03", introduction = "“人類的理性如不落的太陽”，由規則與理性鑄成的東區，總會為你提供意想不到的AVG武裝。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[210] = {sortid = 210, typeid = 2, chapterid = 13, chaptersort = 4, number = "1-3-1", name = "西面調查", plot_first = "1ST/1ST_03A", plot_last = "1ST/1ST_03Ae", checkpointid = 901118, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_04", introduction = "在古老群山環繞的西面，究竟沉睡著何種秘密？", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[211] = {sortid = 211, typeid = 2, chapterid = 13, chaptersort = 5, number = "1-3-2", name = "東面調查", plot_first = "1ST/1ST_03B", plot_last = "1ST/1ST_03Be", checkpointid = 901122, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_05", introduction = "針對東面進行的調查即將開始，“遊隼”已準備就緒。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[212] = {sortid = 212, typeid = 2, chapterid = 13, chaptersort = 6, number = "1-4", name = "一市之長", plot_first = "1ST/1ST_04", plot_last = "0", checkpointid = 901135, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_06", introduction = "東西兩面皆調查無果，可即便是無價值的情報，也必須一一整理，上報市長。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[213] = {sortid = 213, typeid = 2, chapterid = 13, chaptersort = 7, number = "1-5", name = "疑霧重重", plot_first = "1ST/1ST_05", plot_last = "0", checkpointid = 901141, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_07", introduction = "一切所見無不使人疑惑，無論是不明蒼霧，市長古怪的態度，還是東區街道所上演的插曲——", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[214] = {sortid = 214, typeid = 2, chapterid = 13, chaptersort = 8, number = "1-6-1", name = "聖女的秘密", plot_first = "1ST/1ST_06A", plot_last = "0", checkpointid = 901106, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_02", introduction = "你應邀前往教堂，而那人小鬼大的聖女梅莉雅早早便已在此等候。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[215] = {sortid = 215, typeid = 2, chapterid = 13, chaptersort = 9, number = "1-6-2", name = "希夏的願望", plot_first = "1ST/1ST_06B", plot_last = "0", checkpointid = 901145, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_08", introduction = "你應邀去見希夏，導遊般熱情的她會為你透露些什麼呢？", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[216] = {sortid = 216, typeid = 2, chapterid = 13, chaptersort = 10, number = "1-7-1", name = "神前所證", plot_first = "1ST/1ST_07A", plot_last = "0", checkpointid = 901108, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_09", introduction = "即便有些突然，你還是接受了這場於神前舉行的決鬥。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[217] = {sortid = 217, typeid = 2, chapterid = 13, chaptersort = 11, number = "1-7-2", name = "花河訪客", plot_first = "1ST/1ST_07B", plot_last = "0", checkpointid = 901151, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_10", introduction = "在冒險盡頭，希夏珍藏之物，以及她為之奮鬥的理由，赫然顯現眼前。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[218] = {sortid = 218, typeid = 2, chapterid = 13, chaptersort = 12, number = "1-8", name = "交錯點", plot_first = "1ST/1ST_08", plot_last = "0", checkpointid = 901153, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_11", introduction = "因為你的到來，東西兩邊產生了些許交叉。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[219] = {sortid = 219, typeid = 2, chapterid = 13, chaptersort = 13, number = "1-9", name = "帷幕之後", plot_first = "1ST/1ST_09", plot_last = "0", checkpointid = 901137, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_06", introduction = "帷幕之後，仍有許多秘密悄然孕育著什麼。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[220] = {sortid = 220, typeid = 2, chapterid = 13, chaptersort = 14, number = "1-10", name = "兩方行路", plot_first = "1ST/1ST_10", plot_last = "0", checkpointid = 901155, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_12", introduction = "造訪珀因雷德的第二日，事態似乎朝著危險的方向傾塌。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[221] = {sortid = 221, typeid = 2, chapterid = 13, chaptersort = 15, number = "1-11", name = "思潮湧動", plot_first = "1ST/1ST_11", plot_last = "0", checkpointid = 901110, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_02", introduction = "珂斯嘉德與希夏分別展開了行動，在前方等待她們的是——", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[222] = {sortid = 222, typeid = 2, chapterid = 13, chaptersort = 16, number = "1-12", name = "時代斷裂處", plot_first = "1ST/1ST_12", plot_last = "0", checkpointid = 901124, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_05", introduction = "珀因雷德的現狀，不只因空間分裂，也是因時代斷裂。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[223] = {sortid = 223, typeid = 2, chapterid = 13, chaptersort = 17, number = "1-13", name = "現代的神跡", plot_first = "1ST/1ST_13", plot_last = "0", checkpointid = 901115, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_13", introduction = "無人不想重現神跡，縱令他們的方式不盡相同。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[224] = {sortid = 224, typeid = 2, chapterid = 13, chaptersort = 18, number = "1-14", name = "再會面", plot_first = "1ST/1ST_14", plot_last = "0", checkpointid = 901139, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_06", introduction = "你再一次前往市長室，這是否會是你們的最後一次會面？", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[225] = {sortid = 225, typeid = 2, chapterid = 13, chaptersort = 19, number = "1-15", name = "被竊的命運", plot_first = "1ST/1ST_15", plot_last = "1ST/1ST_15e", checkpointid = 901143, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_14", introduction = "於不同的戰場，決定珀因雷德命運的戰鬥將要開始。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[226] = {sortid = 226, typeid = 2, chapterid = 13, chaptersort = 20, number = "1-16", name = "珀因雷德之橋", plot_first = "1ST/1ST_16", plot_last = "0", checkpointid = 901147, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_15", introduction = "被封鎖多年的橋，希夏心懷已久的願望，終於到了迎來終結的時刻。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[227] = {sortid = 227, typeid = 2, chapterid = 13, chaptersort = 21, number = "1-17", name = "罪與贖", plot_first = "1ST/1ST_17", plot_last = "0", checkpointid = 901126, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_16", introduction = "關於罪的故事，關於贖的故事，關於被竊走的命運，以及勇氣與奇跡的故事。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[228] = {sortid = 228, typeid = 2, chapterid = 13, chaptersort = 22, number = "1-18", name = "匯集的希望", plot_first = "1ST/1ST_18", plot_last = "0", checkpointid = 901128, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_05", introduction = "大戰當前，希望終匯集於此，猶如千年前的聖者與罪人。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[229] = {sortid = 229, typeid = 2, chapterid = 13, chaptersort = 23, number = "1-19", name = "亙古不易之光", plot_first = "1ST/1ST_19", plot_last = "0", checkpointid = 901130, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_17", introduction = "作為珀因雷德的文化象征，失竊聖物的真相無疑將鼓舞人們，而後，再度引出另一重真相——", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[230] = {sortid = 230, typeid = 2, chapterid = 13, chaptersort = 24, number = "1-20", name = "向著新篇章", plot_first = "1ST/1ST_20", plot_last = "0", checkpointid = 901134, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_05", introduction = "歷史總是如此，總是毫不留戀過去，匆匆忙翻開一頁新章。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[231] = {sortid = 231, typeid = 2, chapterid = 13, chaptersort = 25, number = "0-1", name = "祝聖之橋", plot_first = "1ST/1ST_chahua1", plot_last = "0", checkpointid = 901163, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_01", introduction = "經由祝聖之橋抵達城區，這是專屬於貴客的禮儀。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[232] = {sortid = 232, typeid = 2, chapterid = 13, chaptersort = 26, number = "0-2", name = "神前決鬥", plot_first = "1ST/1ST_chahua2", plot_last = "0", checkpointid = 901164, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_09", introduction = "神前決鬥，你與珂斯嘉德的心靈之交。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[233] = {sortid = 233, typeid = 2, chapterid = 13, chaptersort = 27, number = "0-3", name = "聖多瑪斯橋", plot_first = "1ST/1ST_chahua3", plot_last = "0", checkpointid = 901165, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_08", introduction = "這座橋既象征著人與人的決裂，又象征著人與人的溝通。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[234] = {sortid = 234, typeid = 2, chapterid = 13, chaptersort = 28, number = "0-4", name = "畫中意", plot_first = "1ST/1ST_chahua4", plot_last = "0", checkpointid = 901166, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_10", introduction = "她潛藏的情感總是通過畫來傳遞。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[235] = {sortid = 235, typeid = 2, chapterid = 13, chaptersort = 29, number = "0-5", name = "“神跡”", plot_first = "1ST/1ST_chahua5", plot_last = "0", checkpointid = 901167, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_18", introduction = "這就是現代的神跡，儘管大多數人類不願意接受現實。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[236] = {sortid = 236, typeid = 2, chapterid = 13, chaptersort = 30, number = "0-6", name = "祈禱", plot_first = "1ST/1ST_chahua6", plot_last = "0", checkpointid = 901168, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_16", introduction = "出淤泥而不染，未必適合她，但她仍會露出聖潔的一面。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[237] = {sortid = 237, typeid = 2, chapterid = 13, chaptersort = 31, number = "0-7", name = "聖物之劍", plot_first = "1ST/1ST_chahua7", plot_last = "0", checkpointid = 901169, picture = "ArtGallery/PlotCg/1ST/1ST_guanqia_17", introduction = "時代更迭，人心善變，但仍有光芒，亙古不易，驅散黑暗。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[238] = {sortid = 238, typeid = 2, chapterid = 14, chaptersort = 1, number = "1-1", name = "三個舞台", plot_first = "qihuahuodong/QiHua_01", plot_last = "0", checkpointid = 901201, picture = "ArtGallery/PlotCg/QiHua/QiHua_01", introduction = "萬事皆已準備就緒，同一時間的三個舞台，你與諸位駕駛員將展開各自的作戰。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[239] = {sortid = 239, typeid = 2, chapterid = 14, chaptersort = 2, number = "1-2", name = "俱焚之焰-上", plot_first = "qihuahuodong/QiHua_02", plot_last = "0", checkpointid = 901202, picture = "ArtGallery/PlotCg/QiHua/QiHua_09", introduction = "創造永遠比毀滅更難，但有時，創造只能建立於毀滅之上。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[240] = {sortid = 240, typeid = 2, chapterid = 14, chaptersort = 3, number = "1-3", name = "俱焚之焰-下", plot_first = "qihuahuodong/QiHua_02e", plot_last = "0", checkpointid = 901203, picture = "ArtGallery/PlotCg/QiHua/QiHua_02", introduction = "現在，有一座森林等著我們去燒。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[241] = {sortid = 241, typeid = 2, chapterid = 14, chaptersort = 4, number = "1-4", name = "席間密語", plot_first = "qihuahuodong/QiHua_03", plot_last = "0", checkpointid = 901204, picture = "ArtGallery/PlotCg/QiHua/QiHua_03", introduction = "舞台之外，席間也正上演著自己的故事。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[242] = {sortid = 242, typeid = 2, chapterid = 14, chaptersort = 5, number = "1-5", name = "星海交融-上", plot_first = "qihuahuodong/QiHua_04", plot_last = "0", checkpointid = 901205, picture = "ArtGallery/PlotCg/QiHua/QiHua_10", introduction = "海面輝映星空，星空染上海色，在這裡，老師與學生的立場也似乎發生了轉換。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[243] = {sortid = 243, typeid = 2, chapterid = 14, chaptersort = 6, number = "1-6", name = "星海交融-下", plot_first = "qihuahuodong/QiHua_04e", plot_last = "0", checkpointid = 901206, picture = "ArtGallery/PlotCg/QiHua/QiHua_04", introduction = "抓水母大成功。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[244] = {sortid = 244, typeid = 2, chapterid = 14, chaptersort = 7, number = "1-7", name = "幕後舞者", plot_first = "qihuahuodong/QiHua_05", plot_last = "0", checkpointid = 901207, picture = "ArtGallery/PlotCg/QiHua/QiHua_05", introduction = "想要參與一場戲，並不非得親身登台。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[245] = {sortid = 245, typeid = 2, chapterid = 14, chaptersort = 8, number = "1-8", name = "傳聞、幻覺與夢想-上", plot_first = "qihuahuodong/QiHua_06", plot_last = "0", checkpointid = 901208, picture = "ArtGallery/PlotCg/QiHua/QiHua_11", introduction = "早熟少女的夢想，只是距離所產生的幻覺嗎？無關事實，她有她自己的道路。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[246] = {sortid = 246, typeid = 2, chapterid = 14, chaptersort = 9, number = "1-9", name = "傳聞、幻覺與夢想-下", plot_first = "qihuahuodong/QiHua_06e", plot_last = "0", checkpointid = 901209, picture = "ArtGallery/PlotCg/QiHua/QiHua_06", introduction = "最後一組的戰鬥也落下帷幕，但事情仍未結束……或者高潮才剛剛拉開序幕。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[247] = {sortid = 247, typeid = 2, chapterid = 14, chaptersort = 10, number = "1-10", name = "愛與奇跡的偶像", plot_first = "qihuahuodong/QiHua_07", plot_last = "0", checkpointid = 901210, picture = "ArtGallery/PlotCg/QiHua/QiHua_07", introduction = "所有的準備，所有的劇目，統統只為這一場演出而存在。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[248] = {sortid = 248, typeid = 2, chapterid = 14, chaptersort = 11, number = "1-11", name = "落幕，而後啟程", plot_first = "qihuahuodong/QiHua_08", plot_last = "0", checkpointid = 901211, picture = "ArtGallery/PlotCg/QiHua/QiHua_08", introduction = "演出的時光稍縱即逝，但在落幕之後，我們仍將歸返另一座舞台，參與起步再晚也不遲的漫長好戲。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[249] = {sortid = 249, typeid = 2, chapterid = 15, chaptersort = 1, number = "1-1", name = "早上好，世界", plot_first = "2024_XH2/2024_XH2_01", plot_last = "0", checkpointid = 901300, picture = "ArtGallery/PlotCg/2024_XH2/2024xh1", introduction = "少女匍伏在你的身上，耳邊能聽到她平穩的呼吸聲，洗發露的甜味撲鼻而來。不管是從視覺上還是觸覺上的情報都印證著——這是一位赤裸的少女。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[250] = {sortid = 250, typeid = 2, chapterid = 15, chaptersort = 2, number = "1-2", name = "女主角宇宙", plot_first = "2024_XH2/2024_XH2_02", plot_last = "0", checkpointid = 901301, picture = "ArtGallery/PlotCg/2024_XH2/2024xh2", introduction = "女主角宇宙，顧名思義，是只有女主角存在的世界，而你作為唯一的男人亂入了這個宇宙……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[251] = {sortid = 251, typeid = 2, chapterid = 15, chaptersort = 3, number = "1-3", name = "隱藏身份的重要性", plot_first = "2024_XH2/2024_XH2_03", plot_last = "0", checkpointid = 901302, picture = "ArtGallery/PlotCg/2024_XH2/2024xh3", introduction = "“如果不想被你的女主角們囚禁起來當寵物的話，就乖乖隱藏好身份。”撿到你的少女如是說道。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[252] = {sortid = 252, typeid = 2, chapterid = 15, chaptersort = 4, number = "1-4", name = "像是友人的“某人”", plot_first = "2024_XH2/2024_XH2_04", plot_last = "0", checkpointid = 901303, picture = "ArtGallery/PlotCg/2024_XH2/2024xh4", introduction = "你確信，現在一定是在做夢——要不然為什麼那個莉莉絲會用甜美的嗓音喊你“主人大人”。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[253] = {sortid = 253, typeid = 2, chapterid = 15, chaptersort = 5, number = "1-5", name = "【光】", plot_first = "2024_XH2/2024_XH2_05", plot_last = "0", checkpointid = 901304, picture = "ArtGallery/PlotCg/2024_XH2/2024xh5", introduction = "讓你沒想到的是，你的偽裝被莉莉絲一眼識破……最糟糕的是這件事已經引起了在餐廳就餐的伊莎貝拉等人的注意。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[254] = {sortid = 254, typeid = 2, chapterid = 15, chaptersort = 6, number = "1-6", name = "光之國最強的公主", plot_first = "2024_XH2/2024_XH2_06", plot_last = "0", checkpointid = 901305, picture = "ArtGallery/PlotCg/2024_XH2/2024xh6", introduction = "“吾乃領航和斯卡蒂的基因結合培養出的，光之國最強的公主。”", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[255] = {sortid = 255, typeid = 2, chapterid = 15, chaptersort = 7, number = "1-7", name = "暗黑女僕大師", plot_first = "2024_XH2/2024_XH2_07", plot_last = "0", checkpointid = 901306, picture = "ArtGallery/PlotCg/2024_XH2/2024xh7", introduction = "“為什麼要學斯卡蒂說話？”莉莉絲滿臉嫌棄地看著你。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[256] = {sortid = 256, typeid = 2, chapterid = 15, chaptersort = 8, number = "1-8", name = "騎士為何而哭泣", plot_first = "2024_XH2/2024_XH2_08", plot_last = "2024_XH2/2024_XH2_08e", checkpointid = 901307, picture = "ArtGallery/PlotCg/2024_XH2/2024xh8", introduction = "你在沙灘上遇見了一位哭泣的少女……為什麼？", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[257] = {sortid = 257, typeid = 2, chapterid = 15, chaptersort = 9, number = "1-9", name = "被害者其一", plot_first = "2024_XH2/2024_XH2_09", plot_last = "2024_XH2/2024_XH2_09e", checkpointid = 901308, picture = "ArtGallery/PlotCg/2024_XH2/2024xh9", introduction = "“我、我、我作為騎士，當、當然要在公主殿下睡覺的時候守護他！”發現了你秘密的奧菲利亞這麼說道。與此同時，答應為你們領路的莉莉絲遭到了一場襲擊。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[258] = {sortid = 258, typeid = 2, chapterid = 15, chaptersort = 10, number = "1-10", name = "海濱樂園的日常", plot_first = "2024_XH2/2024_XH2_10", plot_last = "0", checkpointid = 901309, picture = "ArtGallery/PlotCg/2024_XH2/2024xh10", introduction = "經過幾日的對照實驗，在晚上脫光大家衣服的兇手終於被你找到了，那就是——", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[259] = {sortid = 259, typeid = 2, chapterid = 15, chaptersort = 11, number = "1-11", name = "不屬於這個宇宙的亡靈", plot_first = "2024_XH2/2024_XH2_11", plot_last = "2024_XH2/2024_XH2_11e", checkpointid = 901310, picture = "ArtGallery/PlotCg/2024_XH2/2024xh11", introduction = "在大量感情聚集的海濱樂園，其中有著能否定宇宙規律、真正殺死女主角的執念體。伊莎貝拉等人就是為了調查此事而來。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[260] = {sortid = 260, typeid = 2, chapterid = 15, chaptersort = 12, number = "1-12", name = "未來已死", plot_first = "2024_XH2/2024_XH2_12", plot_last = "0", checkpointid = 901311, picture = "ArtGallery/PlotCg/2024_XH2/2024xh12", introduction = "名為未來的人，卻早已告別未來。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[261] = {sortid = 261, typeid = 2, chapterid = 15, chaptersort = 13, number = "1-13", name = "莉莉絲與莉莉絲", plot_first = "2024_XH2/2024_XH2_13", plot_last = "0", checkpointid = 901325, picture = "ArtGallery/PlotCg/2024_XH2/2024xh13", introduction = "在意識彌留之際，莉莉絲見到了把她召喚來這個宇宙的罪魁禍首——那是這個宇宙的莉莉絲，在醞釀著某種陰謀。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[262] = {sortid = 262, typeid = 2, chapterid = 15, chaptersort = 14, number = "1-14", name = "美夢依舊", plot_first = "2024_XH2/2024_XH2_14", plot_last = "0", checkpointid = 901326, picture = "ArtGallery/PlotCg/2024_XH2/2024xh14", introduction = "未來在夢中再一次見到了家人……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[263] = {sortid = 263, typeid = 2, chapterid = 15, chaptersort = 15, number = "1-15", name = "影之國來客", plot_first = "2024_XH2/2024_XH2_15", plot_last = "0", checkpointid = 901327, picture = "ArtGallery/PlotCg/2024_XH2/2024xh15", introduction = "會長和王女是曾經與你共同對抗巴哈姆特的夥伴，她們遵循著某種承諾來到了你的面前。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[264] = {sortid = 264, typeid = 2, chapterid = 15, chaptersort = 16, number = "1-16", name = "宇宙大罪", plot_first = "2024_XH2/2024_XH2_16", plot_last = "0", checkpointid = 901328, picture = "ArtGallery/PlotCg/2024_XH2/2024xh16", introduction = "新增一例“宇宙大罪”案例，“假冒女主角罪”，“入侵宇宙罪”，“破壞宇宙和平罪”——海濱樂園管理員未來，將被處以驅逐之刑。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[265] = {sortid = 265, typeid = 2, chapterid = 15, chaptersort = 17, number = "1-17A", name = "死者為我", plot_first = "2024_XH2/2024_XH2_17_1", plot_last = "0", checkpointid = 901329, picture = "ArtGallery/PlotCg/2024_XH2/2024xh17.1", introduction = "我已經沒有時間了……連一分一秒都沒辦法向前進……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[266] = {sortid = 266, typeid = 2, chapterid = 15, chaptersort = 18, number = "1-17B", name = "愚忠騎士", plot_first = "2024_XH2/2024_XH2_17_2", plot_last = "0", checkpointid = 901330, picture = "ArtGallery/PlotCg/2024_XH2/2024xh17.2", introduction = "我們的宇宙可還沒小到連一個小女孩和她的樂園都容不下！！", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[267] = {sortid = 267, typeid = 2, chapterid = 15, chaptersort = 19, number = "1-18", name = "審判日", plot_first = "2024_XH2/2024_XH2_18", plot_last = "2024_XH2/2024_XH2_18e", checkpointid = 901331, picture = "ArtGallery/PlotCg/2024_XH2/2024xh18", introduction = "隨著最後的鐘聲落下，審判正式開始。但是——有人對“這場鬧劇”提出了反對意見。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[268] = {sortid = 268, typeid = 2, chapterid = 15, chaptersort = 20, number = "1-19", name = "女主角", plot_first = "2024_XH2/2024_XH2_19", plot_last = "2024_XH2/2024_XH2_19e", checkpointid = 901332, picture = "ArtGallery/PlotCg/2024_XH2/2024xh19", introduction = "“我的人生和你一點關係都沒有！聽到了嗎！我既不是你的女主角也不屬於這裏！即使如此……即便如此……我……我還是好想和你在一起啊……”", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[269] = {sortid = 269, typeid = 2, chapterid = 15, chaptersort = 21, number = "1-20", name = "未來，回應期待", plot_first = "2024_XH2/2024_XH2_20", plot_last = "2024_XH2/2024_XH2_20e", checkpointid = 901333, picture = "ArtGallery/PlotCg/2024_XH2/2024xh20", introduction = "無論是家人也好，夥伴的愛的也罷，我早就清楚——我接受了大家很多的照顧。所以——我要回應大家的期待了——", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[270] = {sortid = 270, typeid = 2, chapterid = 15, chaptersort = 22, number = "1-21", name = "後日談", plot_first = "2024_XH2/2024_XH2_21", plot_last = "0", checkpointid = 901334, picture = "ArtGallery/PlotCg/2024_XH2/2024xh21", introduction = "戰鬥結束之後，未來最終決定回到自己的宇宙，臨別之際她與你定下了約定。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[271] = {sortid = 271, typeid = 2, chapterid = 15, chaptersort = 23, number = "1-22", name = "早上好，未來", plot_first = "2024_XH2/2024_XH2_22", plot_last = "0", checkpointid = 901364, picture = "ArtGallery/PlotCg/2024_XH2/2024xh22", introduction = "這是並未記載在影之國編年史2中的絕密的後日談。是至今未被確認的未來。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[272] = {sortid = 272, typeid = 2, chapterid = 7, chaptersort = 1, number = "1-1", name = "救援信號", plot_first = "XUE/xue_1", plot_last = "XUE/xue_1e", checkpointid = 900501, picture = "ArtGallery/PlotCg/XUE/XUE_1", introduction = "接收到斷斷續續的救援信號，雪鸮小隊頂著十年難遇的暴風雪前往調查。可是在前往信號來源處的路途中遭受了不明敵人的攻擊。大雪遮蔽了敵人的一切，唯一可以確定的是，敵人是個原罪……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[273] = {sortid = 273, typeid = 2, chapterid = 7, chaptersort = 2, number = "1-2", name = "意外情況", plot_first = "XUE/xue_2", plot_last = "0", checkpointid = 900502, picture = "ArtGallery/PlotCg/XUE/XUE_2", introduction = "在莉迪婭的掩護斷後下，熱尼亞與莫莫卡順利找到了發出救援信號的位置，而信號的發出者竟是瓦爾基裏小隊的隊員莉法。但出乎二人意料的是，這裏除了莉法之外還困著更多人……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[274] = {sortid = 274, typeid = 2, chapterid = 7, chaptersort = 3, number = "1-3", name = "停電", plot_first = "XUE/xue_3", plot_last = "0", checkpointid = 900503, picture = "ArtGallery/PlotCg/XUE/XUE_3", introduction = "莉迪婭僥倖擺脫了原罪，拖著傷痕累累的身體撐到了冰炬基地，同事也帶來了有關原罪的些許資訊。就在幾人商討接下來如何行動之時，基地的能源卻出現了問題……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[275] = {sortid = 275, typeid = 2, chapterid = 7, chaptersort = 4, number = "1-4", name = "基地深處", plot_first = "XUE/xue_4", plot_last = "0", checkpointid = 900504, picture = "ArtGallery/PlotCg/XUE/XUE_4", introduction = "三人輕鬆擊殺掉侵入的原罪，來到了基地的深處。展現在三人眼前的是一個時代的淚痕，一個曾經製造了歷史上最嚴重的人造災難的裝置——尼姆比斯電場發生器……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[276] = {sortid = 276, typeid = 2, chapterid = 7, chaptersort = 5, number = "1-5", name = "另一方向", plot_first = "XUE/xue_5", plot_last = "0", checkpointid = 900505, picture = "ArtGallery/PlotCg/XUE/XUE_5", introduction = "通過損壞的門，三人發現了基地後方的出口。在離這不遠的地方就有一座樞紐城市……就在幾人商討下一步行動時，一種悄然的襲擊正在侵蝕熱尼亞的核心……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[277] = {sortid = 277, typeid = 2, chapterid = 7, chaptersort = 6, number = "1-6", name = "包圍圈", plot_first = "XUE/xue_6", plot_last = "0", checkpointid = 900506, picture = "ArtGallery/PlotCg/XUE/XUE_6", introduction = "翌日淩晨，大雪終於停下，天空露出了原本的藍色。但沒人因此感到高興，因為通過偵查這裏已經被原罪包圍。僅憑四位駕駛員或許可以解決雪地中密密麻麻的低等原罪，但絕對對抗不了准罪級……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[278] = {sortid = 278, typeid = 2, chapterid = 7, chaptersort = 7, number = "1-7", name = "隱瞞", plot_first = "XUE/xue_7", plot_last = "0", checkpointid = 900507, picture = "ArtGallery/PlotCg/XUE/XUE_7", introduction = "在安置完普通居民們後，莫莫卡突然意識到了莉迪婭計畫的不對勁。莉迪婭或許想要犧牲自己來獲取其他幾人的安全撤離。在生死存亡之際，莉法卻提出了一個驚世駭俗的計畫……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[279] = {sortid = 279, typeid = 2, chapterid = 7, chaptersort = 8, number = "1-8", name = "“災難”", plot_first = "XUE/xue_8", plot_last = "XUE/xue_8e", checkpointid = 900508, picture = "ArtGallery/PlotCg/XUE/XUE_8", introduction = "莉迪婭在熱尼亞的手心中醒來，卻找不到莫莫卡和莉法的身影。就在她詢問熱尼亞發生了什麼的時候，一場“災難”從遠處的岩石山壁中升起……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[280] = {sortid = 280, typeid = 2, chapterid = 16, chaptersort = 1, number = "1-1", name = "超能力者們暢聊著過去", plot_first = "1.5year/mmbz_01", plot_last = "0", checkpointid = 901400, picture = "ArtGallery/PlotCg/1.5year/juqingtu_01", introduction = "立直麻將中會輪流坐莊，但是代表莊家的標示從沒有離開過星爍的手邊。遊戲自東場零本場開始，在東場一本場結束。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[281] = {sortid = 281, typeid = 2, chapterid = 16, chaptersort = 2, number = "1-2", name = "阿爾泰婭·維斯受難日", plot_first = "1.5year/mmbz_02", plot_last = "0", checkpointid = 901401, picture = "ArtGallery/PlotCg/1.5year/juqingtu_02", introduction = "少女這麼說著：“我不是較真，只是不喜歡用玩笑把事情敷衍過去。”", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[282] = {sortid = 282, typeid = 2, chapterid = 16, chaptersort = 3, number = "1-3", name = "缸中之腦", plot_first = "1.5year/mmbz_03", plot_last = "0", checkpointid = 901402, picture = "ArtGallery/PlotCg/1.5year/juqingtu_03", introduction = "如果我們發現自己在過去的某一刻，或者說從生下來的時候就被取出大腦，裝在了某個裝置裡——塞繆，我們該怎麼做？", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[283] = {sortid = 283, typeid = 2, chapterid = 16, chaptersort = 4, number = "1-4", name = "今 七實", plot_first = "1.5year/mmbz_04", plot_last = "0", checkpointid = 901403, picture = "ArtGallery/PlotCg/1.5year/juqingtu_04", introduction = "讀音是“Ima Nanami”，反過來讀也是“Ima Nanami”。若是論誰會願意出手幫小妹——那恐怕只有我今七實了。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[284] = {sortid = 284, typeid = 2, chapterid = 16, chaptersort = 5, number = "1-5", name = "曾經我也是一名駕駛員", plot_first = "1.5year/mmbz_05", plot_last = "0", checkpointid = 901404, picture = "ArtGallery/PlotCg/1.5year/juqingtu_05", introduction = "如果要求每一個人都像她——多洛莉絲——不僅從絕望中振作起來，還成為了更好的自己，那無疑是一種強人所難。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[285] = {sortid = 285, typeid = 2, chapterid = 16, chaptersort = 6, number = "1-6", name = "蜥蜴先生的假期", plot_first = "1.5year/mmbz_06", plot_last = "0", checkpointid = 901405, picture = "ArtGallery/PlotCg/1.5year/juqingtu_06", introduction = "科莫多巨蜥比一般的冷血動物都要好動且好鬥，所以它也叫鐵血的熱血的冷血的科莫多巨蜥。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[286] = {sortid = 286, typeid = 2, chapterid = 16, chaptersort = 7, number = "1-7", name = "伊甸之蛇", plot_first = "1.5year/mmbz_07", plot_last = "0", checkpointid = 901406, picture = "ArtGallery/PlotCg/1.5year/juqingtu_07", introduction = "就這樣懷揣著對生活的無望，對未來的絕望，對人生的失望，一輩子痛苦而不幸地活下去吧，她咒罵自己。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[287] = {sortid = 287, typeid = 2, chapterid = 16, chaptersort = 8, number = "1-8", name = "跟蹤狂們魚貫而入", plot_first = "1.5year/mmbz_08", plot_last = "0", checkpointid = 901407, picture = "ArtGallery/PlotCg/1.5year/juqingtu_08", introduction = "我一路尾隨著機車服女性來到了此處，在進行了一番激烈的思想鬥爭後，我推開了別人的家門。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[288] = {sortid = 288, typeid = 2, chapterid = 16, chaptersort = 9, number = "1-9", name = "塞繆", plot_first = "1.5year/mmbz_09", plot_last = "0", checkpointid = 901408, picture = "ArtGallery/PlotCg/1.5year/juqingtu_09", introduction = "偽·通感者阿爾泰婭是真實存在的。而另一人——塞繆，是虛假的？", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[289] = {sortid = 289, typeid = 2, chapterid = 16, chaptersort = 10, number = "1-10", name = "假貨與真貨", plot_first = "1.5year/mmbz_10", plot_last = "0", checkpointid = 901422, picture = "ArtGallery/PlotCg/1.5year/juqingtu_10", introduction = "你們倆個人，只有一個人是真實的，而另一個人，是通過“通感”，欺瞞了所有人的感官，創造出來的“假貨”。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[290] = {sortid = 290, typeid = 2, chapterid = 16, chaptersort = 11, number = "1-11", name = "邁著輕鬆的步伐介入", plot_first = "1.5year/mmbz_11", plot_last = "0", checkpointid = 901423, picture = "ArtGallery/PlotCg/1.5year/juqingtu_11", introduction = "想要幫助某個人，就是這樣簡單的理由——觸手可及的範圍，我從不視而不見。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[291] = {sortid = 291, typeid = 2, chapterid = 16, chaptersort = 12, number = "1-12", name = "請告訴我吧，剎那大人", plot_first = "1.5year/mmbz_12", plot_last = "0", checkpointid = 901424, picture = "ArtGallery/PlotCg/1.5year/juqingtu_12", introduction = "比起原罪，我更加在意——七年前發生了什麼讓你這麼在意，希爾薇。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[292] = {sortid = 292, typeid = 2, chapterid = 16, chaptersort = 13, number = "1-13", name = "無頭騎士與變態頭盔男", plot_first = "1.5year/mmbz_13", plot_last = "0", checkpointid = 901425, picture = "ArtGallery/PlotCg/1.5year/juqingtu_13", introduction = "瓦爾基裏的莉法小姐在我的印象中始終穿著那身女僕裝——她的言行舉止也十分符合大眾印象中的女僕，所以我一直認為莉法小姐是名女僕。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[293] = {sortid = 293, typeid = 2, chapterid = 16, chaptersort = 14, number = "1-14", name = "菲琳，以駕駛員形態出擊", plot_first = "1.5year/mmbz_14", plot_last = "0", checkpointid = 901426, picture = "ArtGallery/PlotCg/1.5year/juqingtu_14", introduction = "如果你長大後的夢想是成為一名駕駛員的話，那我就要在你長大之前徹底殺死你的夢想。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[294] = {sortid = 294, typeid = 2, chapterid = 16, chaptersort = 15, number = "1-15", name = "祝你早安，午安，以及晚安", plot_first = "1.5year/mmbz_15", plot_last = "0", checkpointid = 901427, picture = "ArtGallery/PlotCg/1.5year/juqingtu_15", introduction = "比起阿爾泰婭為了隱藏自己，製造了一個完全虛假的第二人塞繆——還是塞繆為了隱藏自己，創造了一個看起來完全是真實存在的阿爾泰婭更加符合直覺吧？", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[295] = {sortid = 295, typeid = 2, chapterid = 16, chaptersort = 16, number = "1-16", name = "曾用名“塞繆”", plot_first = "1.5year/mmbz_16", plot_last = "0", checkpointid = 901428, picture = "ArtGallery/PlotCg/1.5year/juqingtu_16", introduction = "不要叫我塞繆，這個世界從來不存在“塞繆”，只有阿爾泰婭，阿爾泰婭·維斯。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[296] = {sortid = 296, typeid = 2, chapterid = 16, chaptersort = 17, number = "1-17", name = "救世者們彙聚而來", plot_first = "1.5year/mmbz_17", plot_last = "1.5year/mmbz_17e", checkpointid = 901429, picture = "ArtGallery/PlotCg/1.5year/juqingtu_17", introduction = "——閒話少說，接下來，享受獵殺吧。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[297] = {sortid = 297, typeid = 2, chapterid = 16, chaptersort = 18, number = "1-18", name = "另類救世主", plot_first = "1.5year/mmbz_18", plot_last = "0", checkpointid = 901430, picture = "ArtGallery/PlotCg/1.5year/juqingtu_18", introduction = "尼姆比斯能源通常是無法在人體內儲存的，即使是巨大化的身軀，尼姆比斯能源也是以一個包裹住人體的狀態和人類共存。即便是偽通感者，也無法打破這個定論——人類的身體無法容納尼姆比斯能。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[298] = {sortid = 298, typeid = 2, chapterid = 16, chaptersort = 19, number = "1-19", name = "向這個世界宣告", plot_first = "1.5year/mmbz_19", plot_last = "1.5year/mmbz_19e", checkpointid = 901431, picture = "ArtGallery/PlotCg/1.5year/juqingtu_19", introduction = "無論是壓迫感還是體型，都足以與耶夢加得媲美的原罪正在朝她逼近。九顆腦袋，共計十八只眼睛，從各自不同的角度注視著這名少女——蛇瞳裏面的少女，不管從哪個角度看，都看不出什麼奇特之處。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[299] = {sortid = 299, typeid = 2, chapterid = 16, chaptersort = 20, number = "1-20", name = "法外狂徒", plot_first = "1.5year/mmbz_20", plot_last = "0", checkpointid = 901432, picture = "ArtGallery/PlotCg/1.5year/juqingtu_20", introduction = "我想知道七年前發生了什麼——是什麼毀了我，毀了我們，讓我們的人生變成現在這樣。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[300] = {sortid = 300, typeid = 2, chapterid = 16, chaptersort = 21, number = "1-21", name = "美夢不再", plot_first = "1.5year/mmbz_21", plot_last = "0", checkpointid = 901433, picture = "ArtGallery/PlotCg/1.5year/juqingtu_21", introduction = "這起事件，絕不能算作是單方面的掠奪。是互相索取，是互相依賴。用美夢來逃避現實。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[301] = {sortid = 301, typeid = 2, chapterid = 16, chaptersort = 22, number = "1-22", name = "後日談", plot_first = "1.5year/mmbz_22", plot_last = "0", checkpointid = 901434, picture = "ArtGallery/PlotCg/1.5year/juqingtu_22", introduction = "故事來到了尾聲，而這場只有一個人會感到愉快的麻將對局也不可能再進行下去了。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[302] = {sortid = 302, typeid = 2, chapterid = 10, chaptersort = 1, number = "1-1", name = "重逢", plot_first = "cx/cx_1", plot_last = "0", checkpointid = 900801, picture = "ArtGallery/PlotCg/cx/cx_1", introduction = "從多瑙返回印加的駕駛員柯朗，在所長辦公室裏遇見了意料之外的老熟人。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[303] = {sortid = 303, typeid = 2, chapterid = 10, chaptersort = 2, number = "1-2", name = "初見", plot_first = "cx/cx_2", plot_last = "0", checkpointid = 900802, picture = "ArtGallery/PlotCg/cx/cx_2", introduction = "米拓三區，位於印加西北部的山脈區域，內有數座活火山。這裏不僅是兩人初次見面的地方，也是她們命運的轉折之地。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[304] = {sortid = 304, typeid = 2, chapterid = 10, chaptersort = 3, number = "1-3", name = "研究所", plot_first = "cx/cx_3", plot_last = "0", checkpointid = 900803, picture = "ArtGallery/PlotCg/cx/cx_3", introduction = "兩人開車前往研究所，發現那裏只有一片廢墟，與方才的城鎮沒什麼區別。經過調查，她們發現了可以通往地下的密道。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[305] = {sortid = 305, typeid = 2, chapterid = 10, chaptersort = 4, number = "1-4", name = "赤色晶體", plot_first = "cx/cx_4", plot_last = "0", checkpointid = 900804, picture = "ArtGallery/PlotCg/cx/cx_4", introduction = "在探索研究所的地下區域途中，走廊裏突然響起了詭異的腳步聲……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[306] = {sortid = 306, typeid = 2, chapterid = 10, chaptersort = 5, number = "1-5", name = "傷", plot_first = "cx/cx_5", plot_last = "0", checkpointid = 900805, picture = "ArtGallery/PlotCg/cx/cx_5", introduction = "終於擺脫追逐的三人躲在房間裏，短暫休息片刻。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[307] = {sortid = 307, typeid = 2, chapterid = 10, chaptersort = 6, number = "1-6", name = "偽幻化池", plot_first = "cx/cx_6", plot_last = "0", checkpointid = 900806, picture = "ArtGallery/PlotCg/cx/cx_6", introduction = "與蘇亞娜分開後，維嘉和柯朗（52號）並沒有原路返回，而是來到了一個巨大、空曠的房間……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[308] = {sortid = 308, typeid = 2, chapterid = 10, chaptersort = 7, number = "1-7", name = "脫險……？", plot_first = "cx/cx_7", plot_last = "0", checkpointid = 900807, picture = "ArtGallery/PlotCg/cx/cx_7", introduction = "所幸那只原罪的機動性並不高，給了兩人逃離地下研究所的機會。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[309] = {sortid = 309, typeid = 2, chapterid = 10, chaptersort = 8, number = "1-8", name = "“好久不見。”", plot_first = "cx/cx_8", plot_last = "0", checkpointid = 900808, picture = "ArtGallery/PlotCg/cx/cx_8", introduction = "回憶結束，但人生並不會就此結束。時隔四年，走上不同道路的兩人再次相逢——不。在此重逢的，可不只有她們兩人。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[310] = {sortid = 310, typeid = 2, chapterid = 17, chaptersort = 1, number = "1-1", name = "陌生的熟人", plot_first = "Christmas2024/C1_1", plot_last = "0", checkpointid = 901500, picture = "ArtGallery/PlotCg/Christmas2024/C1-1", introduction = "在最溫馨的節日來到最寒冷的地區出差，前往的途中卻遇到了最陌生的熟人……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[311] = {sortid = 311, typeid = 2, chapterid = 17, chaptersort = 2, number = "1-2", name = "冰湖旅館", plot_first = "Christmas2024/C1_2", plot_last = "0", checkpointid = 901501, picture = "ArtGallery/PlotCg/Christmas2024/C1-2", introduction = "廢棄的老舊旅館終於迎來了新的客人，從鋪在大廳的紅毯可以窺到這裏過去的輝煌……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[312] = {sortid = 312, typeid = 2, chapterid = 17, chaptersort = 3, number = "1-3", name = "第一次", plot_first = "Christmas2024/C1_3", plot_last = "0", checkpointid = 901502, picture = "ArtGallery/PlotCg/Christmas2024/C1-3", introduction = "第一步找到一片厚實的冰面，確保冰下有著活水和魚群。第二步在冰上挖一個直徑約為20釐米的冰洞。第三步往洞內撒入一些餌料靜待一會兒後用下魚竿。第四步等待……無盡的等待……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[313] = {sortid = 313, typeid = 2, chapterid = 17, chaptersort = 4, number = "1-4", name = "聖誕樹", plot_first = "Christmas2024/C1_4", plot_last = "0", checkpointid = 901503, picture = "ArtGallery/PlotCg/Christmas2024/C1-4", introduction = "聖誕樹，需要一顆挺拔的常青樹裝點上燈泡和聖誕裝飾品，是耶誕節必不可缺的一部分……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[314] = {sortid = 314, typeid = 2, chapterid = 17, chaptersort = 5, number = "1-5", name = "“菈伊莎”", plot_first = "Christmas2024/C1_5", plot_last = "0", checkpointid = 901504, picture = "ArtGallery/PlotCg/Christmas2024/C1-5", introduction = "“菈伊莎”一個代表無憂無慮的名字，正適合眼前懵懂而年幼的孩子，但是她體內存在的另一個聲音註定會讓這個美好祝願變成泡影……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[315] = {sortid = 315, typeid = 2, chapterid = 17, chaptersort = 6, number = "1-6", name = "赫洛卡與秘密控制部", plot_first = "Christmas2024/C1_6", plot_last = "0", checkpointid = 901505, picture = "ArtGallery/PlotCg/Christmas2024/C1-6", introduction = "在北極圈之北，寒冷之地的深處，正是第一研究室控制部的所在之處，而能夠掌控這裏的唯有赫洛卡一人……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[316] = {sortid = 316, typeid = 2, chapterid = 17, chaptersort = 7, number = "1-7", name = "平安夜", plot_first = "Christmas2024/C1_7", plot_last = "0", checkpointid = 901506, picture = "ArtGallery/PlotCg/Christmas2024/C1-7", introduction = "在平安夜的鐘聲響起之前，所有人都應該待在家中與親人和好友相聚。將此刻的美好記在心裏，然後用一生去回憶……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[317] = {sortid = 317, typeid = 2, chapterid = 17, chaptersort = 8, number = "1-8", name = "車中夜談", plot_first = "Christmas2024/C1_8", plot_last = "0", checkpointid = 901507, picture = "ArtGallery/PlotCg/Christmas2024/C1-8", introduction = "在卡佳的夜晚漫步或許會遇到夢遊的野獸，針鋒相對或者擦肩而過。槍可以驅趕現實中的動物，或許也能制止心中憤怒的野獸……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[318] = {sortid = 318, typeid = 2, chapterid = 17, chaptersort = 9, number = "1-9", name = "GK計畫", plot_first = "Christmas2024/C1_9", plot_last = "0", checkpointid = 901508, picture = "ArtGallery/PlotCg/Christmas2024/C1-9", introduction = "GK計畫，一個針對高等原罪核心開發的嘗試性實驗專案，停滯不前許久的專案進度，將在今日以一種悲傷、焦慮、宏偉的形式，突破……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[319] = {sortid = 319, typeid = 2, chapterid = 17, chaptersort = 10, number = "1-10", name = "重逢與新生", plot_first = "Christmas2024/C1_10", plot_last = "Christmas2024/C1_10e", checkpointid = 901509, picture = "ArtGallery/PlotCg/Christmas2024/C1-10", introduction = "高昂的叫聲在雪海之上迴響，從屍骸中醒來的巨鯨，舞動金屬巨鰭向著高空遊去。浮游空海的巨鯨，承載著三個人的固執和希望……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[320] = {sortid = 320, typeid = 2, chapterid = 17, chaptersort = 11, number = "1-11", name = "妄想性回憶", plot_first = "Christmas2024/C2_1", plot_last = "0", checkpointid = 901523, picture = "ArtGallery/PlotCg/Christmas2024/C2-1", introduction = "在熟悉的車內醒來，看著似曾相識的場景，昨日的種種悲傷激動，似乎是一場不願記起的噩夢……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[321] = {sortid = 321, typeid = 2, chapterid = 17, chaptersort = 12, number = "1-12", name = "重複迷失", plot_first = "Christmas2024/C2_2", plot_last = "0", checkpointid = 901524, picture = "ArtGallery/PlotCg/Christmas2024/C2-2", introduction = "在熟悉的車內醒來，看著似曾相識的場景，昨日的種種悲傷激動，那絕對不只是一場夢……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[322] = {sortid = 322, typeid = 2, chapterid = 17, chaptersort = 13, number = "1-13", name = "關鍵線索", plot_first = "Christmas2024/C2_3", plot_last = "0", checkpointid = 901525, picture = "ArtGallery/PlotCg/Christmas2024/C2-3", introduction = "在熟悉的車內醒來，看著似曾相識的場景，記不得是第幾次睜開眼，或許這一次能夠找到離開這裏的線索……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[323] = {sortid = 323, typeid = 2, chapterid = 17, chaptersort = 14, number = "1-14", name = "不同的“菈伊莎”", plot_first = "Christmas2024/C2_4", plot_last = "0", checkpointid = 901526, picture = "ArtGallery/PlotCg/Christmas2024/C2-4", introduction = "緊閉的門之後是血色的世界，眼前之人已經不再是記憶中的菈伊莎。來不及思考，子彈已經擊穿了此次迴圈……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[324] = {sortid = 324, typeid = 2, chapterid = 17, chaptersort = 15, number = "1-15", name = "離別", plot_first = "Christmas2024/C2_5", plot_last = "0", checkpointid = 901527, picture = "ArtGallery/PlotCg/Christmas2024/C2-5", introduction = "短暫的重遇之後是永遠的離別……不，還有挽回的機會，在一切塵埃落定之前……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[325] = {sortid = 325, typeid = 2, chapterid = 17, chaptersort = 16, number = "1-16", name = "【伊卡洛斯】", plot_first = "Christmas2024/C2_6", plot_last = "0", checkpointid = 901528, picture = "ArtGallery/PlotCg/Christmas2024/C2-6", introduction = "遊蕩在高空的驚駭巨獸，名為【伊卡洛斯】的巨大鯨魚。現在領航所想的竟然是要從在人類手中拯救原罪……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[326] = {sortid = 326, typeid = 2, chapterid = 17, chaptersort = 17, number = "1-17", name = "人類的天使", plot_first = "Christmas2024/C2_7", plot_last = "0", checkpointid = 901529, picture = "ArtGallery/PlotCg/Christmas2024/C2-7", introduction = "為了拯救伊莉雅，為了接近【伊卡洛斯】，波琳娜毫無顧慮地踏上了通往天堂的臺階，在那裏她將化身天使，如同命中註定……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[327] = {sortid = 327, typeid = 2, chapterid = 17, chaptersort = 18, number = "1-18", name = "拋竿", plot_first = "Christmas2024/C2_8", plot_last = "0", checkpointid = 901530, picture = "ArtGallery/PlotCg/Christmas2024/C2-8", introduction = "一切的準備就緒，目標是遠處天空遊蕩的巨鯨。而現在赫洛卡將拋出那決定性的一竿……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[328] = {sortid = 328, typeid = 2, chapterid = 17, chaptersort = 19, number = "1-19", name = "“嫉妒”", plot_first = "Christmas2024/C2_9", plot_last = "Christmas2024/C2_9e", checkpointid = 901531, picture = "ArtGallery/PlotCg/Christmas2024/C2-9", introduction = "穿梭在【伊卡洛斯】的身體之中，尋找著那泛著藍色光芒的巨大水晶。沒想到在巨鯨的體內竟然還存在著一個巨大的少女，她的名字不是“伊莉雅”不是“菈伊莎”而是“嫉妒”……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[329] = {sortid = 329, typeid = 2, chapterid = 17, chaptersort = 20, number = "1-20", name = "靈魂與記憶的區別", plot_first = "Christmas2024/C2_10", plot_last = "0", checkpointid = 901532, picture = "ArtGallery/PlotCg/Christmas2024/C2-10", introduction = "在記憶世界的深處是由遺忘之物彙聚而成的海洋，菈伊莎將自己拋棄在這裏，作為靈魂來與記憶相制衡……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[330] = {sortid = 330, typeid = 2, chapterid = 17, chaptersort = 21, number = "1-21", name = "不靠譜的聖誕老人", plot_first = "Christmas2024/C2_11", plot_last = "0", checkpointid = 901533, picture = "ArtGallery/PlotCg/Christmas2024/C2-11", introduction = "聖誕老人的雪橇在最巧合的時候來到了最巧合的地方，然而這畢竟不是聖誕老人的雪橇，坐在裏面的也不是個靠譜的聖誕老人……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[331] = {sortid = 331, typeid = 2, chapterid = 17, chaptersort = 22, number = "1-22", name = "無夜可守", plot_first = "Christmas2024/C2_12", plot_last = "0", checkpointid = 901534, picture = "ArtGallery/PlotCg/Christmas2024/C2-12", introduction = "卡佳度過了一個危險的耶誕節，此次的危機也必須有人負起責任。追根溯源，赫洛卡好像就是此次危機的始作俑者，第一研究室控制部也將岌岌可危。難道自此之後守夜人將無夜可守？……或許並非如此。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[332] = {sortid = 332, typeid = 2, chapterid = 18, chaptersort = 1, number = "1-1", name = "領航的孩子", plot_first = "2025_qingrenjie/2025_qingrenjie_01", plot_last = "0", checkpointid = 901600, picture = "ArtGallery/PlotCg/2025_qingrenjie/2025_qingrenjie_01", introduction = "“因為人家有了他的孩子……現在得去找他商量之後該怎麼辦……”陌生的女孩子在尋找著領航，據她所說，她懷上了領航的孩子。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[333] = {sortid = 333, typeid = 2, chapterid = 18, chaptersort = 2, number = "1-2", name = "超級戀愛偵探助手", plot_first = "2025_qingrenjie/2025_qingrenjie_02", plot_last = "0", checkpointid = 901601, picture = "ArtGallery/PlotCg/2025_qingrenjie/2025_qingrenjie_02", introduction = "在解決完關於“孩子”的問題後，未來終於想起了此行的目的——", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[334] = {sortid = 334, typeid = 2, chapterid = 18, chaptersort = 3, number = "1-3", name = "返老還童的秘藥", plot_first = "2025_qingrenjie/2025_qingrenjie_03", plot_last = "0", checkpointid = 901602, picture = "ArtGallery/PlotCg/2025_qingrenjie/2025_qingrenjie_03", introduction = "駕駛員的情書和感情紛紛被奪走……正當朱利烏斯找到了犯人的線索的時候，意外發生了——", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[335] = {sortid = 335, typeid = 2, chapterid = 18, chaptersort = 4, number = "1-4", name = "親嘴解除魔咒吧！", plot_first = "2025_qingrenjie/2025_qingrenjie_04", plot_last = "0", checkpointid = 901603, picture = "ArtGallery/PlotCg/2025_qingrenjie/2025_qingrenjie_04", introduction = "公主遭受的魔咒需要王子的親吻來解除，這是常識，我的朋友。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[336] = {sortid = 336, typeid = 2, chapterid = 18, chaptersort = 5, number = "1-5", name = "亞瑟·潘德拉貢", plot_first = "2025_qingrenjie/2025_qingrenjie_05", plot_last = "0", checkpointid = 901604, picture = "ArtGallery/PlotCg/2025_qingrenjie/2025_qingrenjie_05", introduction = "我名為亞瑟·潘德拉貢，是一位路過的駕駛員。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[337] = {sortid = 337, typeid = 2, chapterid = 18, chaptersort = 6, number = "1-6", name = "能看見未來的名偵探", plot_first = "2025_qingrenjie/2025_qingrenjie_06", plot_last = "0", checkpointid = 901605, picture = "ArtGallery/PlotCg/2025_qingrenjie/2025_qingrenjie_06", introduction = "通過看透未來的方式來破案，真是不得了的名偵探……所以和偵探有什麼關係？", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[338] = {sortid = 338, typeid = 2, chapterid = 18, chaptersort = 7, number = "1-7", name = "名偵探之死", plot_first = "2025_qingrenjie/2025_qingrenjie_07", plot_last = "0", checkpointid = 901606, picture = "ArtGallery/PlotCg/2025_qingrenjie/2025_qingrenjie_07", introduction = "像你這種有作弊能力的偵探，就應該被刪除。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[339] = {sortid = 339, typeid = 2, chapterid = 18, chaptersort = 8, number = "1-8", name = "犯人的顏色是紅色", plot_first = "2025_qingrenjie/2025_qingrenjie_08", plot_last = "0", checkpointid = 901607, picture = "ArtGallery/PlotCg/2025_qingrenjie/2025_qingrenjie_08", introduction = "神秘客（查麗莎）和紅博士再一次出現了。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[340] = {sortid = 340, typeid = 2, chapterid = 18, chaptersort = 9, number = "3-1", name = "致我最喜歡的變態先生", plot_first = "2025_qingrenjie/2025_qingrenjie_09", plot_last = "0", checkpointid = 901615, picture = "ArtGallery/PlotCg/2025_qingrenjie/2025_qingrenjie_09", introduction = "這是我準備給變態先生的告白信！", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[341] = {sortid = 341, typeid = 2, chapterid = 18, chaptersort = 10, number = "3-2", name = "隨後，未來被奪走", plot_first = "2025_qingrenjie/2025_qingrenjie_10", plot_last = "0", checkpointid = 901616, picture = "ArtGallery/PlotCg/2025_qingrenjie/2025_qingrenjie_10", introduction = "未來會在幾天內失去記憶，也就會失去作為“偵探助手”的知識和能力。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[342] = {sortid = 342, typeid = 2, chapterid = 18, chaptersort = 11, number = "3-3", name = "一等一的戀愛大師", plot_first = "2025_qingrenjie/2025_qingrenjie_11", plot_last = "0", checkpointid = 901617, picture = "ArtGallery/PlotCg/2025_qingrenjie/2025_qingrenjie_11", introduction = "雖然我們的戀愛經驗為0，但是我們的戀愛知識是很豐富的。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[343] = {sortid = 343, typeid = 2, chapterid = 18, chaptersort = 12, number = "3-4", name = "紅之初中生", plot_first = "2025_qingrenjie/2025_qingrenjie_12", plot_last = "0", checkpointid = 901618, picture = "ArtGallery/PlotCg/2025_qingrenjie/2025_qingrenjie_12", introduction = "奪走大家感情的真正的犯人，自稱為紅博士。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[344] = {sortid = 344, typeid = 2, chapterid = 18, chaptersort = 13, number = "3-5", name = "絕對戀愛怪盜", plot_first = "2025_qingrenjie/2025_qingrenjie_13", plot_last = "0", checkpointid = 901619, picture = "ArtGallery/PlotCg/2025_qingrenjie/2025_qingrenjie_13", introduction = "第一，絕對不放棄每一位心懷熾烈感情的少女。第二，絕對不放過任何一位搶跑的偷腥貓。第三，絕對戀愛的公平正義。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[345] = {sortid = 345, typeid = 2, chapterid = 18, chaptersort = 14, number = "3-6", name = "機械朱利烏斯原罪", plot_first = "2025_qingrenjie/2025_qingrenjie_14", plot_last = "0", checkpointid = 901620, picture = "ArtGallery/PlotCg/2025_qingrenjie/2025_qingrenjie_14", introduction = "犯人的老巢中停住著以朱利烏斯為原型製作的巨大機器人原罪。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[346] = {sortid = 346, typeid = 2, chapterid = 18, chaptersort = 15, number = "3-7", name = "會哭泣的機器人", plot_first = "2025_qingrenjie/2025_qingrenjie_15", plot_last = "0", checkpointid = 901621, picture = "ArtGallery/PlotCg/2025_qingrenjie/2025_qingrenjie_15", introduction = "這是紅博士對這個世界給出的答案，絕對的生命，另類的原罪——", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[347] = {sortid = 347, typeid = 2, chapterid = 18, chaptersort = 16, number = "3-8", name = "朱利烏斯的告白信", plot_first = "2025_qingrenjie/2025_qingrenjie_16", plot_last = "0", checkpointid = 901622, picture = "ArtGallery/PlotCg/2025_qingrenjie/2025_qingrenjie_16", introduction = "接下來就該去逮捕紅博士了。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[348] = {sortid = 348, typeid = 2, chapterid = 18, chaptersort = 17, number = "3-9", name = "巧克力味的後日談", plot_first = "2025_qingrenjie/2025_qingrenjie_17", plot_last = "0", checkpointid = 901623, picture = "ArtGallery/PlotCg/2025_qingrenjie/2025_qingrenjie_17", introduction = "仿佛置身於一個既美好又有些令人悵然的夢境裡——隨後，我與世界失去了同步——", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[349] = {sortid = 349, typeid = 2, chapterid = 19, chaptersort = 1, number = "1-1", name = "臨時撤退", plot_first = "2year/2year_01", plot_last = "0", checkpointid = 901700, picture = "ArtGallery/PlotCg/2year/2year_01", introduction = "損失過半的駕駛員部隊，無法對被感染成原罪的人類駕駛員動手的幽靈部隊，以及暫時停止活動的原罪方舟……複雜的狀況使得我們暫時撤退。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[350] = {sortid = 350, typeid = 2, chapterid = 19, chaptersort = 2, number = "1-2", name = "D型之死", plot_first = "2year/2year_02", plot_last = "0", checkpointid = 901701, picture = "ArtGallery/PlotCg/2year/2year_02", introduction = "“所謂的擬態人格就是通過技術手段將某個活著的人格複寫進程序中，由此製造出的特殊晶片便被稱為“擬態人格”。”", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[351] = {sortid = 351, typeid = 2, chapterid = 19, chaptersort = 3, number = "1-3", name = "女兒、女兒、以及兵器", plot_first = "2year/2year_00", plot_last = "0", checkpointid = 901702, picture = "ArtGallery/PlotCg/2year/2year_00", introduction = "奧德賽先生的女兒並不止一個……尼莫西妮，以及D型b2的人格數據來源……達芙妮。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[352] = {sortid = 352, typeid = 2, chapterid = 19, chaptersort = 4, number = "1-4", name = "勇者與同伴一號", plot_first = "2year/2year_03", plot_last = "0", checkpointid = 901703, picture = "ArtGallery/PlotCg/2year/2year_03", introduction = "拯救世界之後，倖存的人類得給我打造一個三十米高的雕像，讚頌我，崇拜我，把我的故事永遠流傳下去。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[353] = {sortid = 353, typeid = 2, chapterid = 19, chaptersort = 5, number = "1-5", name = "世界毀滅之後", plot_first = "2year/2year_04", plot_last = "0", checkpointid = 901704, picture = "ArtGallery/PlotCg/2year/2year_04", introduction = "世界毀滅了——如同三流科幻小說裡的情節一樣，我來到了人類文明滅亡後的世界。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[354] = {sortid = 354, typeid = 2, chapterid = 19, chaptersort = 6, number = "1-6", name = "潘多拉引擎", plot_first = "2year/2year_05", plot_last = "0", checkpointid = 901705, picture = "ArtGallery/PlotCg/2year/2year_05", introduction = "我是駕駛員，人類最後的駕駛員——斯珀絲。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[355] = {sortid = 355, typeid = 2, chapterid = 19, chaptersort = 7, number = "1-7", name = "時間旅行者", plot_first = "2year/2year_06", plot_last = "0", checkpointid = 901706, picture = "ArtGallery/PlotCg/2year/2year_06", introduction = "我是勇者，只是撿到一個時間旅行者也沒什麼好大驚小怪的吧。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[356] = {sortid = 356, typeid = 2, chapterid = 19, chaptersort = 8, number = "1-8", name = "抱著貓的少女", plot_first = "2year/2year_07", plot_last = "0", checkpointid = 901707, picture = "ArtGallery/PlotCg/2year/2year_07", introduction = "我們在新切斯頓遇上的第一名居民，是位捧著貓咪的女孩。她正用打量某種少見外來生物（某種意義上沒錯）的目光上下掃視我。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[357] = {sortid = 357, typeid = 2, chapterid = 19, chaptersort = 9, number = "1-9", name = "我已死去", plot_first = "2year/2year_08", plot_last = "0", checkpointid = 901708, picture = "ArtGallery/PlotCg/2year/2year_08", introduction = "多瑙特別聯合部隊的領航，人類唯一的通感者……那位領航犧牲的時候，人類就已經沒有未來了。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[358] = {sortid = 358, typeid = 2, chapterid = 19, chaptersort = 10, number = "1-10", name = "新切斯頓的管理員", plot_first = "2year/2year_09", plot_last = "0", checkpointid = 901709, picture = "ArtGallery/PlotCg/2year/2year_09", introduction = "——查麗莎·德·羅蘭，原艾吉斯王牌駕駛員。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[359] = {sortid = 359, typeid = 2, chapterid = 19, chaptersort = 11, number = "1-11", name = "好久不見", plot_first = "2year/2year_10", plot_last = "0", checkpointid = 901710, picture = "ArtGallery/PlotCg/2year/2year_10", introduction = "她的變化比我想像中要少得多，還是跟以前一樣的長髮，只是頭髮變得更長了，也沒有以前那麼鮮亮了，這或許就是時間流逝帶來的成熟感吧。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[360] = {sortid = 360, typeid = 2, chapterid = 19, chaptersort = 12, number = "3-1", name = "時間線上的交叉線", plot_first = "2year/2year_11", plot_last = "0", checkpointid = 901726, picture = "ArtGallery/PlotCg/2year/2year_11", introduction = "我們失敗的未來與我們還未失敗的未來，查麗莎倖存的未來與查麗莎可能死亡的未來，一切似乎都交匯於二十年前的那一天……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[361] = {sortid = 361, typeid = 2, chapterid = 19, chaptersort = 13, number = "3-2", name = "勇者的疊加態", plot_first = "2year/2year_12", plot_last = "0", checkpointid = 901727, picture = "ArtGallery/PlotCg/2year/2year_11", introduction = "想當勇者的人都死了，但是活著的人中依舊有人想要成為勇者，這個世界最不缺的就是“死而復生”的勇者……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[362] = {sortid = 362, typeid = 2, chapterid = 19, chaptersort = 14, number = "3-3", name = "炙手可熱", plot_first = "2year/2year_13", plot_last = "0", checkpointid = 901728, picture = "ArtGallery/PlotCg/2year/2year_12", introduction = "夜深時分，查麗莎來到我的房間，送來了一份遲到二十年的告白。那一刻，她似乎變回了二十年前的那個任性的女孩……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[363] = {sortid = 363, typeid = 2, chapterid = 19, chaptersort = 15, number = "3-4", name = "作戰計畫", plot_first = "2year/2year_14", plot_last = "0", checkpointid = 901729, picture = "ArtGallery/PlotCg/2year/2year_13", introduction = "重新執行一份失敗過的作戰計畫，結果會有什麼不同嗎？因為存在變數——我，以及“幽靈”……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[364] = {sortid = 364, typeid = 2, chapterid = 19, chaptersort = 16, number = "3-5", name = "文明凋零之處", plot_first = "2year/2year_15", plot_last = "0", checkpointid = 901730, picture = "ArtGallery/PlotCg/2year/2year_14", introduction = "沒有親眼看到文明凋零的過程是種幸運，看看那些人類城市的屍骸，這是我絕對無法接受的未來……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[365] = {sortid = 365, typeid = 2, chapterid = 19, chaptersort = 17, number = "3-6", name = "舊敵·舊敵", plot_first = "2year/2year_16", plot_last = "0", checkpointid = 901731, picture = "ArtGallery/PlotCg/2year/2year_15", introduction = "“斯庫爾”，准罪級原罪，曾經的手下敗將……原來不止一只嗎？……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[366] = {sortid = 366, typeid = 2, chapterid = 19, chaptersort = 18, number = "3-7", name = "拯救過去更要拯救未來", plot_first = "2year/2year_17", plot_last = "2year/2year_17e", checkpointid = 901732, picture = "ArtGallery/PlotCg/2year/2year_16", introduction = "面對“雙狼”的鉗形攻勢，勇者決心要拯救未來，於是“希望”即將從潘多拉魔盒中升起……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[367] = {sortid = 367, typeid = 2, chapterid = 19, chaptersort = 19, number = "3-8", name = "故地重遊", plot_first = "0", plot_last = "2year/2year_18", checkpointid = 901733, picture = "ArtGallery/PlotCg/2year/2year_17", introduction = "重返故地，並沒有重逢的感動，只覺到時間的荒蕪……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[368] = {sortid = 368, typeid = 2, chapterid = 19, chaptersort = 20, number = "3-9", name = "D·Z從過去到未來的幽靈", plot_first = "2year/2year_19", plot_last = "2year/2year_19e", checkpointid = 901734, picture = "ArtGallery/PlotCg/2year/2year_18", introduction = "陰魂不散，如此形容“幽靈”再合適不過。但是我絕對無法原諒，那個高高在上的自己……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[369] = {sortid = 369, typeid = 2, chapterid = 19, chaptersort = 21, number = "3-10", name = "與未來對峙", plot_first = "2year/2year_20", plot_last = "0", checkpointid = 901735, picture = "ArtGallery/PlotCg/2year/2year_19", introduction = "那藏在“幽靈”之下的真身，毀滅世界的罪魁禍首，人類的叛徒，原罪的幫兇……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[370] = {sortid = 370, typeid = 2, chapterid = 19, chaptersort = 22, number = "3-11", name = "最後的希望", plot_first = "2year/2year_21", plot_last = "0", checkpointid = 901736, picture = "ArtGallery/PlotCg/2year/2year_20", introduction = "避難所裏藏著回到過去的辦法，但如果沒有，我希望能給這個世界留下一點希望……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[371] = {sortid = 371, typeid = 2, chapterid = 19, chaptersort = 23, number = "3-12", name = "最終話：勇者，斯珀絲如是說", plot_first = "2year/2year_22", plot_last = "0", checkpointid = 901737, picture = "ArtGallery/PlotCg/2year/2year_21", introduction = "“我送你回去，你幫我拯救世界。”勇者，斯珀絲如是說……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[372] = {sortid = 372, typeid = 2, chapterid = 19, chaptersort = 24, number = "3-13", name = "後日談，留給過去的遺言", plot_first = "2year/2year_23", plot_last = "0", checkpointid = 901738, picture = "ArtGallery/PlotCg/2year/2year_22", introduction = "不知道寫什麼，只希望過去的未來能有所不同吧。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[373] = {sortid = 373, typeid = 2, chapterid = 20, chaptersort = 1, number = "1-1", name = "操縱原罪的少女", plot_first = "MODU/MODU_1", plot_last = "0", checkpointid = 902000, picture = "ArtGallery/PlotCg/modu/juqingtu_01", introduction = "一位穿著軍裝的少女操縱著原罪穿梭在暴動的原罪之中，她究竟是……？", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[374] = {sortid = 374, typeid = 2, chapterid = 20, chaptersort = 2, number = "1-2", name = "“疑似通感者”", plot_first = "MODU/MODU_2", plot_last = "0", checkpointid = 902001, picture = "ArtGallery/PlotCg/modu/juqingtu_02", introduction = "即是“疑似通感者”……又是中二病嗎……？", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[375] = {sortid = 375, typeid = 2, chapterid = 20, chaptersort = 3, number = "1-3", name = "你好，異世界", plot_first = "MODU/MODU_3", plot_last = "0", checkpointid = 902002, picture = "ArtGallery/PlotCg/modu/juqingtu_03", introduction = "就如同異空間【魔都】與怪物【醜鬼】忽然出現在她們的世界那樣離奇——少女們逐漸察覺她們來到了異世界。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[376] = {sortid = 376, typeid = 2, chapterid = 20, chaptersort = 4, number = "1-4", name = "“超能力”者們", plot_first = "MODU/MODU_4", plot_last = "0", checkpointid = 902003, picture = "ArtGallery/PlotCg/modu/juqingtu_04", introduction = "把手臂化作武器的女人和操控著頭發戰斗的女人，正在與準罪級原罪激烈地對抗著。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[377] = {sortid = 377, typeid = 2, chapterid = 20, chaptersort = 5, number = "1-5", name = "【貝希摩斯】討伐會議", plot_first = "MODU/MODU_5", plot_last = "0", checkpointid = 902004, picture = "ArtGallery/PlotCg/modu/juqingtu_05", introduction = "魔防隊追求著回去的辦法，艾吉斯則是追求消滅準罪級原罪。【貝希摩斯】的討伐戰即將展開——", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[378] = {sortid = 378, typeid = 2, chapterid = 20, chaptersort = 6, number = "1-6", name = "異世界的櫻花", plot_first = "MODU/MODU_6", plot_last = "0", checkpointid = 902005, picture = "ArtGallery/PlotCg/modu/juqingtu_06", introduction = "……九州……異世界竟然也有櫻花嗎？", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[379] = {sortid = 379, typeid = 2, chapterid = 20, chaptersort = 7, number = "3-1", name = "超能力怪盜計劃", plot_first = "MODU/MODU_7", plot_last = "0", checkpointid = 902021, picture = "ArtGallery/PlotCg/modu/juqingtu_07", introduction = "衣食住行……流落異世界的駿河朱朱和出雲天花需要解決的關鍵問題就是——沒有錢。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[380] = {sortid = 380, typeid = 2, chapterid = 20, chaptersort = 8, number = "3-2", name = "王牌", plot_first = "MODU/MODU_8", plot_last = "0", checkpointid = 902022, picture = "ArtGallery/PlotCg/modu/juqingtu_08", introduction = "【星變·希望·實驗型】，史蔕芬妮博士的得意之作，是她在收集了你們的身體數據、血樣樣本、裝備需求之後制作的幻化道具。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[381] = {sortid = 381, typeid = 2, chapterid = 20, chaptersort = 9, number = "3-3", name = "精致睡眠大作戰", plot_first = "MODU/MODU_9", plot_last = "MODU/MODU_9e", checkpointid = 902023, picture = "ArtGallery/PlotCg/modu/juqingtu_09", introduction = "為了保護大家以後的精致睡眠，駿河朱朱出擊！！！", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[382] = {sortid = 382, typeid = 2, chapterid = 20, chaptersort = 10, number = "3-4", name = "夜談", plot_first = "MODU/MODU_10", plot_last = "0", checkpointid = 902024, picture = "ArtGallery/PlotCg/modu/juqingtu_10", introduction = "睡不著的靑羽，睡不著的日萬凛……以及睡不著的京香，在這个深夜相遇了。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[383] = {sortid = 383, typeid = 2, chapterid = 20, chaptersort = 11, number = "3-5", name = "斬首任務", plot_first = "MODU/MODU_11", plot_last = "0", checkpointid = 902025, picture = "ArtGallery/PlotCg/modu/juqingtu_11", introduction = "艾吉斯接到了【貝希摩斯】出現的消息，討伐戰的成員們陸續集合，向著準罪級原罪而去。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[384] = {sortid = 384, typeid = 2, chapterid = 20, chaptersort = 12, number = "3-6", name = "貝希摩斯", plot_first = "MODU/MODU_12", plot_last = "0", checkpointid = 902026, picture = "ArtGallery/PlotCg/modu/juqingtu_12", introduction = "準罪級原罪貝希摩斯，像是移動要塞一樣的原罪——", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[385] = {sortid = 385, typeid = 2, chapterid = 20, chaptersort = 13, number = "3-7", name = "延續春天", plot_first = "MODU/MODU_13", plot_last = "0", checkpointid = 902027, picture = "ArtGallery/PlotCg/modu/juqingtu_13", introduction = "我要——把那些“可能會讓人傷心的未來”斬落在“現在這个時點”，成為一份“幷不重要的過去”！", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
