[387] = {sortid = 387, typeid = 2, chapterid = 21, chaptersort = 1, number = "1-1", name = "屁股與喫飯與女兒", plot_first = "2025_XH3/XH3_1", plot_last = "0", checkpointid = 902100, picture = "ArtGallery/PlotCg/2025_XH3/juqingtu_01", introduction = "再一次出現在影之國編年史的你，從沉睡中醒來發現自己被某位女主角捆綁了，這位女主角自稱是他的女兒——", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
