[389] = {sortid = 389, typeid = 2, chapterid = 21, chaptersort = 3, number = "1-3", name = "又有錢又年輕的爸爸", plot_first = "2025_XH3/XH3_3", plot_last = "0", checkpointid = 902102, picture = "ArtGallery/PlotCg/2025_XH3/juqingtu_03", introduction = "“爸爸從來沒有帶我來遊樂園玩過，所以我從小時候就一直很憧憬。”她訴説著這樣的話，想要你和她一起去遊樂園玩。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[390] = {sortid = 390, typeid = 2, chapterid = 21, chaptersort = 4, number = "1-4", name = "【宇宙大災】red", plot_first = "2025_XH3/XH3_4", plot_last = "0", checkpointid = 902103, picture = "ArtGallery/PlotCg/2025_XH3/juqingtu_04", introduction = "據説她以【人類的感情】作為食物，如果不想被她吸干變成行尸走肉的話，就不要和她正面交鋒……是非常危險的【宇宙大災】。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
