[412] = {sortid = 412, typeid = 2, chapterid = 22, chaptersort = 3, number = "1-3", name = "除罪的“魔女”", plot_first = "2025_2_5year/2025_2_5year_03", plot_last = "0", checkpointid = 902202, picture = "ArtGallery/PlotCg/2025_2_5year/juqingtu_03", introduction = "自槍管中逬發的火焰，如魔法般收割著原罪的生命，沒人知曉被稱為魔女的少女只是个想要保護自己的膽小鬼……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[413] = {sortid = 413, typeid = 2, chapterid = 22, chaptersort = 4, number = "1-4", name = "降落", plot_first = "2025_2_5year/2025_2_5year_04", plot_last = "0", checkpointid = 902203, picture = "ArtGallery/PlotCg/2025_2_5year/juqingtu_04", introduction = "從昏暗的降落艙內醒來，我的大腦還處在迷茫之中，我下意識地伸手卻觸碰到一个熟悉的柔軟物體……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[414] = {sortid = 414, typeid = 2, chapterid = 22, chaptersort = 5, number = "1-5", name = "蟬與黃雀與黃雀……", plot_first = "2025_2_5year/2025_2_5year_05", plot_last = "2025_2_5year/2025_2_5year_05e", checkpointid = 902204, picture = "ArtGallery/PlotCg/2025_2_5year/juqingtu_05", introduction = "追蹤變成了一場無聊的螳螂捕蟬式鬧劇，但是黃雀似乎有點太多了……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
