[417] = {sortid = 417, typeid = 2, chapterid = 22, chaptersort = 8, number = "1-8", name = "便利店之夜", plot_first = "2025_2_5year/2025_2_5year_08", plot_last = "2025_2_5year/2025_2_5year_08e", checkpointid = 902207, picture = "ArtGallery/PlotCg/2025_2_5year/juqingtu_08", introduction = "藍山的夜晚黑暗而靜謐，小小的便利店便成了這黑暗中唯一的光明……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[418] = {sortid = 418, typeid = 2, chapterid = 22, chaptersort = 9, number = "1-9", name = "默奇森大厦", plot_first = "2025_2_5year/2025_2_5year_09", plot_last = "0", checkpointid = 902208, picture = "ArtGallery/PlotCg/2025_2_5year/juqingtu_09", introduction = "坐落在藍山的中心點，毫無爭議的最高建築，默奇森大厦從過去矗立到現在，見證了藍山近代的興衰……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[419] = {sortid = 419, typeid = 2, chapterid = 22, chaptersort = 10, number = "1-10", name = "地獄來電？", plot_first = "2025_2_5year/2025_2_5year_10", plot_last = "0", checkpointid = 902209, picture = "ArtGallery/PlotCg/2025_2_5year/juqingtu_10", introduction = "正當我們以為赫洛卡已經慘遭毒手之時，通訊器中卻傳來了她的聲音，聽上去似乎幷不是從地獄打來的電話……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[420] = {sortid = 420, typeid = 2, chapterid = 22, chaptersort = 11, number = "3-1", name = "姐妹", plot_first = "2025_2_5year/2025_2_5year_11", plot_last = "0", checkpointid = 902225, picture = "ArtGallery/PlotCg/2025_2_5year/juqingtu_11", introduction = "米夏是姐姐，米婭是妹妹，米夏感覺似乎自己已經很久沒有這樣和妹妹面對面説話了……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[421] = {sortid = 421, typeid = 2, chapterid = 22, chaptersort = 12, number = "3-2", name = "100%的謊言", plot_first = "2025_2_5year/2025_2_5year_12", plot_last = "0", checkpointid = 902226, picture = "ArtGallery/PlotCg/2025_2_5year/juqingtu_12", introduction = "100%適格率？我……我嗎？不對不對不對，這不可能……眞的是我嗎？……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[422] = {sortid = 422, typeid = 2, chapterid = 22, chaptersort = 13, number = "3-3", name = "歧路", plot_first = "2025_2_5year/2025_2_5year_13", plot_last = "0", checkpointid = 902227, picture = "ArtGallery/PlotCg/2025_2_5year/juqingtu_13", introduction = "藍山的歷史有一部分與多瑙相銜接，藍山和多瑙就像一對同根同源的姐妹，可是如今卻走上了不同道路……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[423] = {sortid = 423, typeid = 2, chapterid = 22, chaptersort = 14, number = "3-4", name = "鼠群", plot_first = "2025_2_5year/2025_2_5year_14", plot_last = "0", checkpointid = 902228, picture = "ArtGallery/PlotCg/2025_2_5year/juqingtu_14", introduction = "籠子已經被被打開，成群的老鼠正是阿沙西婭手下最可怕的軍隊……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[424] = {sortid = 424, typeid = 2, chapterid = 22, chaptersort = 15, number = "3-5", name = "圍追堵截", plot_first = "2025_2_5year/2025_2_5year_15", plot_last = "2025_2_5year/2025_2_5year_15e", checkpointid = 902229, picture = "ArtGallery/PlotCg/2025_2_5year/juqingtu_15", introduction = "奔跑在藍山的街頭，我眞的很想享受沿途的風景，可是背後的老鼠們幷不會給我慢下來的時間……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[425] = {sortid = 425, typeid = 2, chapterid = 22, chaptersort = 16, number = "3-6", name = "逃離", plot_first = "2025_2_5year/2025_2_5year_16", plot_last = "2025_2_5year/2025_2_5year_16e", checkpointid = 902230, picture = "ArtGallery/PlotCg/2025_2_5year/juqingtu_16", introduction = "她所想要做的事，只是逃離這裏，逃離地球……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[426] = {sortid = 426, typeid = 2, chapterid = 22, chaptersort = 17, number = "3-7", name = "進化的原始積累", plot_first = "2025_2_5year/2025_2_5year_17", plot_last = "2025_2_5year/2025_2_5year_17e", checkpointid = 902231, picture = "ArtGallery/PlotCg/2025_2_5year/juqingtu_17", introduction = "生命演化和做生意一樣，沒有原始積累就無法進化，無法進化的結果，就是被世界所淘汰……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[427] = {sortid = 427, typeid = 2, chapterid = 22, chaptersort = 18, number = "3-8", name = "“空無之殻”", plot_first = "2025_2_5year/2025_2_5year_18", plot_last = "2025_2_5year/2025_2_5year_18e", checkpointid = 902232, picture = "ArtGallery/PlotCg/2025_2_5year/juqingtu_18", introduction = "於毁滅前夕誕生，孕育虛無的空殻，承載最初的希望……它幷非“完美”本身，而是容納“完美”的容器……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[428] = {sortid = 428, typeid = 2, chapterid = 22, chaptersort = 19, number = "3-9", name = "清算開始", plot_first = "2025_2_5year/2025_2_5year_19", plot_last = "0", checkpointid = 902233, picture = "ArtGallery/PlotCg/2025_2_5year/juqingtu_19", introduction = "從天而降的黑色幽靈，預示著對藍山的清算正式開始……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[429] = {sortid = 429, typeid = 2, chapterid = 22, chaptersort = 20, number = "3-10", name = "如果……", plot_first = "2025_2_5year/2025_2_5year_20", plot_last = "2025_2_5year/2025_2_5year_20e", checkpointid = 902234, picture = "ArtGallery/PlotCg/2025_2_5year/juqingtu_20", introduction = "如果我能早點接受自己的無能，如果我能早點舍棄那無意義的自尊，如果……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[430] = {sortid = 430, typeid = 2, chapterid = 22, chaptersort = 21, number = "3-11", name = "向宇宙進發", plot_first = "2025_2_5year/2025_2_5year_21", plot_last = "0", checkpointid = 902235, picture = "ArtGallery/PlotCg/2025_2_5year/juqingtu_21", introduction = "最終她還是實現那个任性的夢想……", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[431] = {sortid = 431, typeid = 2, chapterid = 23, chaptersort = 1, number = "1-1", name = "冬日午後", plot_first = "2025_christmas/2025_christmas_01", plot_last = "0", checkpointid = 902300, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_01", introduction = "掙脫不請自來的夢，在冷空氣的包裹中失手打翻牀頭的水杯——綜上所述，只是她生活中一个平平無奇的清晨。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[432] = {sortid = 432, typeid = 2, chapterid = 23, chaptersort = 2, number = "1-2", name = "調制飲料，不變人生", plot_first = "2025_christmas/2025_christmas_02", plot_last = "0", checkpointid = 902301, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_02", introduction = "對大部分人來説的平凡周五，某个人命途多舛的寶貴假日。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[433] = {sortid = 433, typeid = 2, chapterid = 23, chaptersort = 3, number = "1-3", name = "致親愛的我——", plot_first = "2025_christmas/2025_christmas_03", plot_last = "0", checkpointid = 902302, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_03", introduction = "不是每个人的生命都能在襁褓和親人的環繞下開始的。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[434] = {sortid = 434, typeid = 2, chapterid = 23, chaptersort = 4, number = "1-4", name = "偶遇，以及偶遇", plot_first = "2025_christmas/2025_christmas_04", plot_last = "0", checkpointid = 902303, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_04", introduction = "起初，沒有人覺得這一晚的相遇裏存在任何命運的必然。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[435] = {sortid = 435, typeid = 2, chapterid = 23, chaptersort = 5, number = "1-5", name = "停滯的人", plot_first = "2025_christmas/2025_christmas_05", plot_last = "0", checkpointid = 902304, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_05", introduction = "只從一位好鄰居的角度來説，她做的事總是無可挑剔。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[436] = {sortid = 436, typeid = 2, chapterid = 23, chaptersort = 6, number = "1-6", name = "轉動的齒輪", plot_first = "2025_christmas/2025_christmas_06", plot_last = "0", checkpointid = 902305, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_06", introduction = "那一天，伊斯卡拉習慣使然地撞上了（其實還挺重要的）命運", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[437] = {sortid = 437, typeid = 2, chapterid = 23, chaptersort = 7, number = "1-7", name = "緩步向前；被迫回首", plot_first = "2025_christmas/2025_christmas_07", plot_last = "0", checkpointid = 902306, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_07", introduction = "人确實不會總能知道朋友的生活具體有了什麽變化。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[438] = {sortid = 438, typeid = 2, chapterid = 23, chaptersort = 8, number = "1-8", name = "夜談", plot_first = "2025_christmas/2025_christmas_08", plot_last = "0", checkpointid = 902307, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_08", introduction = "壞消息，麻煩大了。好消息，她從來不懂什麽叫獨善其身。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[439] = {sortid = 439, typeid = 2, chapterid = 23, chaptersort = 9, number = "1-9", name = "再見了，美好假日", plot_first = "2025_christmas/2025_christmas_09", plot_last = "0", checkpointid = 902308, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_09", introduction = "會在最恰好的時機被卷入最麻煩的事，這也是主人公的必備素養。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[440] = {sortid = 440, typeid = 2, chapterid = 23, chaptersort = 10, number = "1-10", name = "意外的熟人", plot_first = "2025_christmas/2025_christmas_10", plot_last = "0", checkpointid = 902309, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_10", introduction = "不同人的生活會被一些總是精力過賸的家夥連接在一起。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[441] = {sortid = 441, typeid = 2, chapterid = 23, chaptersort = 11, number = "3-1", name = "安寧不再", plot_first = "2025_christmas/2025_christmas_11", plot_last = "0", checkpointid = 902325, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_11", introduction = "麻煩，是唯一永遠會如約定那樣找上門來的東西。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[442] = {sortid = 442, typeid = 2, chapterid = 23, chaptersort = 12, number = "3-2", name = "貴客來訪", plot_first = "2025_christmas/2025_christmas_12", plot_last = "0", checkpointid = 902326, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_12", introduction = "一年都不會發生幾件大事的那棟辦公樓有了意外的客人。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[443] = {sortid = 443, typeid = 2, chapterid = 23, chaptersort = 13, number = "3-3", name = "一千个灰暗的日子", plot_first = "2025_christmas/2025_christmas_13", plot_last = "0", checkpointid = 902327, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_13", introduction = "她依稀記得，那段日子裏，工作起碼不算自己睡不好覺的直接原因。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[444] = {sortid = 444, typeid = 2, chapterid = 23, chaptersort = 14, number = "3-4", name = "合流", plot_first = "2025_christmas/2025_christmas_14", plot_last = "0", checkpointid = 902328, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_14", introduction = "一个順利過頭的計劃有可能會把當事人自己甩在後面。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[445] = {sortid = 445, typeid = 2, chapterid = 23, chaptersort = 15, number = "3-5", name = "冰川之下", plot_first = "2025_christmas/2025_christmas_15", plot_last = "0", checkpointid = 902329, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_15", introduction = "那些身處臺面之下的人往往能有更多的行動空間——對敵對友都是如此。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[446] = {sortid = 446, typeid = 2, chapterid = 23, chaptersort = 16, number = "3-6", name = "一時興起", plot_first = "2025_christmas/2025_christmas_16", plot_last = "0", checkpointid = 902330, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_16", introduction = "保護欲、責任心——在上訴這一切之前，她只感覺到一股令人煩躁的熟悉。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[447] = {sortid = 447, typeid = 2, chapterid = 23, chaptersort = 17, number = "3-7", name = "入口", plot_first = "2025_christmas/2025_christmas_17", plot_last = "0", checkpointid = 902331, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_17", introduction = "無論是答案還是過去，都像在招手一般陳列在那裏。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[448] = {sortid = 448, typeid = 2, chapterid = 23, chaptersort = 18, number = "3-8", name = "禍不單行", plot_first = "2025_christmas/2025_christmas_18", plot_last = "0", checkpointid = 902332, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_18", introduction = "生活總會變著法子推人一把，哪怕是以絶對會把人惹毛的方式。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[449] = {sortid = 449, typeid = 2, chapterid = 23, chaptersort = 19, number = "3-9", name = "各司其職", plot_first = "2025_christmas/2025_christmas_19", plot_last = "0", checkpointid = 902333, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_19", introduction = "想要掙脫過去的人，無法擁有過去的人，以及厭惡著過去的人。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[450] = {sortid = 450, typeid = 2, chapterid = 23, chaptersort = 20, number = "3-10", name = "老友聚會", plot_first = "2025_christmas/2025_christmas_20", plot_last = "0", checkpointid = 902334, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_20", introduction = "伊斯卡拉一向不擅長應付葉芙根尼婭。要命的是，對方對這一點心知肚明。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[451] = {sortid = 451, typeid = 2, chapterid = 23, chaptersort = 21, number = "3-11", name = "涌動的黃昏", plot_first = "2025_christmas/2025_christmas_21", plot_last = "0", checkpointid = 902335, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_21", introduction = "天氣晴朗，目標簡潔，計劃明确——嗯，沒有任何會出意外的空間。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[452] = {sortid = 452, typeid = 2, chapterid = 23, chaptersort = 22, number = "3-12", name = "倒計時", plot_first = "2025_christmas/2025_christmas_22", plot_last = "0", checkpointid = 902336, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_22", introduction = "冬日的晚霞中，懸著一塊不祥的時鍾。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[453] = {sortid = 453, typeid = 2, chapterid = 23, chaptersort = 23, number = "3-13", name = "最糟的一天", plot_first = "2025_christmas/2025_christmas_23", plot_last = "0", checkpointid = 902337, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_23", introduction = "以及只是稍微沒那麽糟糕的無數天。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[454] = {sortid = 454, typeid = 2, chapterid = 23, chaptersort = 24, number = "3-14", name = "再見。以及，祝你平安", plot_first = "2025_christmas/2025_christmas_24", plot_last = "0", checkpointid = 902338, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_24", introduction = "電話最大的意義，就是讓那些該被説出的話能跨越距離", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[455] = {sortid = 455, typeid = 2, chapterid = 23, chaptersort = 25, number = "3-15", name = "強加之約", plot_first = "2025_christmas/2025_christmas_25", plot_last = "0", checkpointid = 902339, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_25", introduction = "你沒有拒絶的權利。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[456] = {sortid = 456, typeid = 2, chapterid = 23, chaptersort = 26, number = "3-16", name = "曙暮光", plot_first = "2025_christmas/2025_christmas_26", plot_last = "0", checkpointid = 902340, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_26", introduction = "朝陽與落日，在散射出的光芒上並沒有很大區別。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[457] = {sortid = 457, typeid = 2, chapterid = 23, chaptersort = 27, number = "3-17", name = "新日伊始", plot_first = "2025_christmas/2025_christmas_27", plot_last = "0", checkpointid = 902341, picture = "ArtGallery/PlotCg/2025_christmas/juqingtu_27", introduction = "一起異變草草收場，無數事情尙在前方。。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[458] = {sortid = 458, typeid = 2, chapterid = 24, chaptersort = 1, number = "1-1", name = "往事如海水涌來", plot_first = "MODU2/MODU2_1", plot_last = "0", checkpointid = 902500, picture = "ArtGallery/PlotCg/MODU2/C1-1", introduction = "在學校裏的事情，和同伴分別時的事情，如海水一樣，一件件涌上心頭。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[459] = {sortid = 459, typeid = 2, chapterid = 24, chaptersort = 2, number = "1-2", name = "陰影不曾散去", plot_first = "MODU2/MODU2_2", plot_last = "MODU2/MODU2_2e", checkpointid = 902501, picture = "ArtGallery/PlotCg/MODU2/C1-2", introduction = "警報響起，籠罩在人們身上的陰影再度襲來，而這一次，似乎有些不一般。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[460] = {sortid = 460, typeid = 2, chapterid = 24, chaptersort = 3, number = "1-3", name = "陌生的天花板？不，是浴室", plot_first = "MODU2/MODU2_3", plot_last = "0", checkpointid = 902502, picture = "ArtGallery/PlotCg/MODU2/C1-3", introduction = "陌生的天花板，已經見過很多次了，但陌生的浴室，還是第一次。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[461] = {sortid = 461, typeid = 2, chapterid = 24, chaptersort = 4, number = "1-4", name = "似是而非的世界", plot_first = "MODU2/MODU2_4", plot_last = "0", checkpointid = 902503, picture = "ArtGallery/PlotCg/MODU2/C1-4", introduction = "似是而非的歷史，似是而非的人，似是而非的城市，和記憶中的很像，但和記憶中的又不一樣。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[462] = {sortid = 462, typeid = 2, chapterid = 24, chaptersort = 5, number = "1-5", name = "令人感動的重逢", plot_first = "MODU2/MODU2_5", plot_last = "0", checkpointid = 902504, picture = "ArtGallery/PlotCg/MODU2/C1-5", introduction = "有時候不只是和故人重逢很感動，和敵人重逢，也是一種感動。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[463] = {sortid = 463, typeid = 2, chapterid = 24, chaptersort = 6, number = "1-6", name = "她看見了亡靈", plot_first = "MODU2/MODU2_6", plot_last = "0", checkpointid = 902505, picture = "ArtGallery/PlotCg/MODU2/C1-6", introduction = "毫無疑問，多洛莉絲所知的那个名字，屬於一个亡靈。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[464] = {sortid = 464, typeid = 2, chapterid = 24, chaptersort = 7, number = "1-7", name = "被束之高閣的最強", plot_first = "MODU2/MODU2_7", plot_last = "0", checkpointid = 902506, picture = "ArtGallery/PlotCg/MODU2/C1-7", introduction = "弱者不喜歡和強者一起玩遊戲，因爲會失去遊戲體驗。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[465] = {sortid = 465, typeid = 2, chapterid = 24, chaptersort = 8, number = "1-8", name = "人生商談", plot_first = "MODU2/MODU2_8", plot_last = "0", checkpointid = 902507, picture = "ArtGallery/PlotCg/MODU2/C1-8", introduction = "她有些事情想聊，關於未來的事情，關於末日的事情，關於她和她的事情。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[466] = {sortid = 466, typeid = 2, chapterid = 24, chaptersort = 9, number = "1-9", name = "貪婪的願望總不少見", plot_first = "MODU2/MODU2_9", plot_last = "0", checkpointid = 902508, picture = "ArtGallery/PlotCg/MODU2/C1-9", introduction = "如果能無條件實現一个願望的話，人的貪婪便會輕易顯現出來吧。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[467] = {sortid = 467, typeid = 2, chapterid = 24, chaptersort = 10, number = "1-10", name = "分頭行動", plot_first = "MODU2/MODU2_10", plot_last = "0", checkpointid = 902509, picture = "ArtGallery/PlotCg/MODU2/C1-10", introduction = "分頭行動是最有效率的辦事方案，前提是分頭行動的人眞的有在做事。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[468] = {sortid = 468, typeid = 2, chapterid = 24, chaptersort = 11, number = "1-11", name = "因偷懶而畱下的漏洞", plot_first = "MODU2/MODU2_11", plot_last = "0", checkpointid = 902525, picture = "ArtGallery/PlotCg/MODU2/C1-11", introduction = "可以接受世界是不完美的，但世界有漏洞，那就不對。", "0", "0", "0", "0", "0", "0", "0", "0", "0"},
